INSERT INTO [dbo].[Courses] ([Id], [Title], [Description], [ThumbnailUrl], [IsPublished], [SyllabusId], [CreatedByUserId], [CreatedAt], [UpdatedAt], [Category], [PresenterProfileId], [CategoryId], [Price]) VALUES ('1e92c718-9223-4788-823b-df66de62504e', N'Trí Tuệ Nhân Tạo Ứng Dụng', N'Học phần cung cấp kiến thức và kỹ năng cơ bản về trí tuệ nhân tạo (TTNT), khai thác, quản lý và phân tích dữ liệu, ứng dụng TTNT để cá nhân hóa học tập và giải quyết vấn đề thực tiễn.', N'/storage/course-thumbnails/1e92c71892234788823bdf66de62504e-8d5ba5acc50649eeb4d6dc36959263e3.png', 1, 'e7aa31cf-8b21-4f03-bebe-002d2adcfced', '680028f3-06a9-41ad-b64c-87721edd6a03', '2026-06-12T15:27:03.572896', '2026-06-12T15:48:41.224661', N'UiUxDesign', NULL, 'd53abe70-450e-4b6d-9a0b-ebd486b8ed80', 3000);
INSERT INTO [dbo].[Courses] ([Id], [Title], [Description], [ThumbnailUrl], [IsPublished], [SyllabusId], [CreatedByUserId], [CreatedAt], [UpdatedAt], [Category], [PresenterProfileId], [CategoryId], [Price]) VALUES ('75bde32c-630e-4ebd-acca-e374c71dade8', N'Lập trình trên môi trường Windows', N'Học phần cung cấp kiến thức và kỹ năng cho sinh viên để xây dựng được ứng dụng chạy trên nền hệ điều hành Windows. Sinh viên có thể tự xây dựng được ứng dụng có giao diện đồ họa người dùng. Sinh viên có được kỹ năng trong việc sử dụng công cụ chuyên nghiệp để phát triển ứng dụng, cụ thể là công cụ Visual Studio. Học phần được xây dựng với các nội dung: Kiến thức tổng quan về .NET Framework; Xây dựng ứng dụng Windows Form thông qua ngôn ngữ C#; Xây dựng ứng dụng Windows Form kết nối với hệ cơ sở dữ liệu Microsoft SQL Server.', NULL, 0, 'a61f2e95-2d2b-477d-95a9-1dec7bb5e04e', '680028f3-06a9-41ad-b64c-87721edd6a03', '2026-06-17T08:42:15.884723', NULL, N'UiUxDesign', NULL, '52f4d42e-a716-4fd9-8c7b-1283a15307b9', 599000);
INSERT INTO [dbo].[Courses] ([Id], [Title], [Description], [ThumbnailUrl], [IsPublished], [SyllabusId], [CreatedByUserId], [CreatedAt], [UpdatedAt], [Category], [PresenterProfileId], [CategoryId], [Price]) VALUES ('444403f4-83a5-4542-a8cb-fc1378fb6ce0', N'Lập trình hướng đối tượng', N'Học phần giới thiệu các khái niệm, nguyên lý và phương pháp lập trình hướng đối tượng, hướng dẫn thiết kế và xây dựng ứng dụng thực tế bằng ngôn ngữ Java.', N'/storage/course-thumbnails/444403f483a54542a8cbfc1378fb6ce0-bbbd6fccfffb406086787415e5b3769f.jpeg', 1, '9b1603f2-edf5-4f3e-b516-6fc259109207', '680028f3-06a9-41ad-b64c-87721edd6a03', '2026-06-12T13:11:28.997285', '2026-06-12T15:48:42.965201', N'UiUxDesign', NULL, 'd53abe70-450e-4b6d-9a0b-ebd486b8ed80', 3000);
