INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('cace5340-7112-4c93-8329-125e56e2340c', 'cad5ffa7-35aa-42a7-9ed5-e47d94546bd9', N'Đặc điểm của lớp trừu tượng', N'Các đặc điểm và lưu ý khi sử dụng lớp trừu tượng.', 3, N'Đặc điểm của lớp trừu tượng', N'/storage/video/cace5340-7112-4c93-8329-125e56e2340c.mp4', N'/storage/audio/cace5340-7112-4c93-8329-125e56e2340c.mp3', 63, '2026-06-12T13:11:29.007847', '2026-06-12T13:47:00.789805', N'Chào mừng các bạn đến với bài học hôm nay về đặc điểm của lớp trừu tượng trong lập trình hướng đối tượng bằng Java. Trong bài học này, chúng ta sẽ tìm hiểu các đặc điểm chính của lớp trừu tượng và những lưu ý quan trọng khi sử dụng lớp này trong thiết kế phần mềm. Lớp trừu tượng là một khái niệm quan trọng giúp chúng ta xây dựng các cấu trúc linh hoạt và dễ bảo trì. Hãy cùng bắt đầu!', N'[{"SlideNumber":1,"Title":"Kh\u00E1i ni\u1EC7m l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing abstract shape symbolizing hidden complexity, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["L\u1EDBp kh\u00F4ng th\u1EC3 kh\u1EDFi t\u1EA1o \u0111\u1ED1i t\u01B0\u1EE3ng tr\u1EF1c ti\u1EBFp","Ch\u1EE9a c\u00E1c ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng v\u00E0 ph\u01B0\u01A1ng th\u1EE9c c\u00F3 th\u00E2n","\u0110\u1ECBnh ngh\u0129a khu\u00F4n m\u1EABu cho c\u00E1c l\u1EDBp con"],"Speake