INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('38c98941-6528-4636-a70e-1a54b69d03ff', '440378dd-42a8-420d-a977-d6c957353bc3', N'Tính kế thừa', N'Khái niệm và ứng dụng tính kế thừa trong OOP.', 4, N'Tính kế thừa', N'/storage/video/38c98941-6528-4636-a70e-1a54b69d03ff.mp4', N'/storage/audio/38c98941-6528-4636-a70e-1a54b69d03ff.mp3', 47, '2026-06-12T13:11:29.007833', '2026-06-12T13:21:26.790575', N'Chào mừng các bạn đến với bài học về tính kế thừa trong lập trình hướng đối tượng. Trong bài học này, chúng ta sẽ tìm hiểu khái niệm kế thừa, vai trò và cách ứng dụng tính kế thừa để tái sử dụng mã nguồn và mở rộng chức năng trong các ứng dụng thực tế. Tính kế thừa cho phép một lớp con thừa hưởng các thuộc tính và phương thức từ lớp cha, giúp giảm thiểu sự trùng lặp và tăng tính tổ chức cho chương trình. Chúng ta cũng sẽ xem xét ví dụ minh họa và các lưu ý khi sử dụng kế thừa trong Java. Hãy bắt đầu ngay bây giờ!', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u v\u1EC1 t\u00EDnh k\u1EBF th\u1EEBa","ImageKeyword":"Flat vector illustration, minimalist corporate style, a tree with branches extending upward symbolizing growth and inheritance, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Kh\u00E1i ni\u1EC7m k\u1EBF th\u1EEBa trong OOP","L\u1EDBp cha v\u00E0 l\u1EDBp con","T\u00E1i s\u1EED d\u1EE5ng m\u00E3 ngu\u1ED3n"],"SpeakerNotes":"Slide n\u00E0y gi\u1EDBi thi\u1EC7u t\u1