INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('fff29238-7232-4ede-b53d-1dafca3ed0cb', '5d9b1662-8b9c-4ba5-ad65-273618ab982b', N'Giao diện với Swing', N'Sử dụng thư viện Swing để xây dựng giao diện.', 3, N'Giao diện với Swing', N'/storage/video/fff29238-7232-4ede-b53d-1dafca3ed0cb.mp4', N'/storage/audio/fff29238-7232-4ede-b53d-1dafca3ed0cb.mp3', 53, '2026-06-12T13:11:29.007863', '2026-06-12T14:03:59.810359', N'Chào mừng các bạn đến với bài học về giao diện với Swing trong lập trình Java. Trong bài học này, chúng ta sẽ tìm hiểu cách sử dụng thư viện Swing để xây dựng giao diện người dùng hiệu quả và trực quan. Đầu tiên, chúng ta sẽ khám phá các thành phần cơ bản của Swing, tiếp theo là cách tổ chức các thành phần này trong cửa sổ ứng dụng. Sau đó, chúng ta sẽ học cách xử lý sự kiện để giao diện có thể tương tác với người dùng. Cuối cùng, chúng ta sẽ cùng thực hành xây dựng một giao diện đơn giản sử dụng Swing. Hãy bắt đầu ngay bây giờ!', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u v\u1EC1 Swing","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing abstract network of interconnected nodes symbolizing a framework, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Th\u01B0 vi\u1EC7n GUI c\u1EE7a Java","Cung c\u1EA5p c\u00E1c th\u00E0nh ph\u1EA7n giao di\u1EC7n","D\u1EF1a tr\u00EAn AWT nh\u01B0ng m\u1EA1nh m\u1EBD h\u01A1n"],"SpeakerNotes":"S