INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('b938c391-32d6-4817-b2b4-1fd5b08f0f7e', '64279396-80b4-40a7-8c12-004529c6e429', N'Khái niệm giao diện - Interface', N'Định nghĩa và vai trò của interface trong Java.', 1, N'Khái niệm giao diện - Interface', N'/storage/video/b938c391-32d6-4817-b2b4-1fd5b08f0f7e.mp4', N'/storage/audio/b938c391-32d6-4817-b2b4-1fd5b08f0f7e.mp3', 61, '2026-06-12T13:11:29.007854', '2026-06-12T13:52:54.175628', N'Chào mừng các bạn đến với bài học về khái niệm giao diện trong Java. Trong lập trình hướng đối tượng, giao diện hay interface đóng vai trò quan trọng trong việc định nghĩa các phương thức mà một lớp phải triển khai. Interface giúp chúng ta xây dựng các ứng dụng linh hoạt, dễ bảo trì và mở rộng. Hôm nay, chúng ta sẽ tìm hiểu định nghĩa, vai trò và cách sử dụng interface trong Java một cách chi tiết và dễ hiểu.', N'[{"SlideNumber":1,"Title":"\u0110\u1ECBnh ngh\u0129a Interface trong Java","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract interconnected shapes symbolizing connection and structure, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Interface l\u00E0 m\u1ED9t ki\u1EC3u d\u1EEF li\u1EC7u tr\u1EEBu t\u01B0\u1EE3ng","Ch\u1EC9 ch\u1EE9a c\u00E1c ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng v\u00E0 h\u1EB1ng s\u1ED1","\u0110\u1ECBnh ngh\u0129a c\u00E1c ph\u01B0\u01A1ng th\u1EE9c m\u00E0 l\u1EDBp 