INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('73a2d34e-8f5d-4bc7-bfa5-2a221d8cc33d', '5a5469be-efd9-46af-b1be-4b869274aee1', N'Triển khai hệ thống và đánh giá', N'Triển khai, đánh giá và hoàn thiện hệ thống TTNT.', 2, N'Triển khai AI; Đánh giá hệ thống; Hoàn thiện dự án', N'/storage/video/73a2d34e-8f5d-4bc7-bfa5-2a221d8cc33d.mp4', N'/storage/audio/73a2d34e-8f5d-4bc7-bfa5-2a221d8cc33d.mp3', 34, '2026-06-12T15:27:03.596108', '2026-06-12T15:48:06.673756', N'Khi bắt đầu triển khai hệ thống trí tuệ nhân tạo, việc chuẩn bị môi trường vận hành là bước quan trọng đầu tiên. Chúng ta cần đảm bảo phần cứng, phần mềm và dữ liệu đều sẵn sàng để hệ thống hoạt động hiệu quả.
INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('a6f42f8f-00d7-47d6-9bbf-2b51a2db91fa', '5d9b1662-8b9c-4ba5-ad65-273618ab982b', N'Thành phần lập trình giao diện', N'Các thành phần cơ bản trong lập trình giao diện với Java Swing.', 1, N'Thành phần lập trình giao diện', N'/storage/video/a6f42f8f-00d7-47d6-9bbf-2b51a2db91fa.mp4', N'/storage/audio/a6f42f8f-00d7-47d6-9bbf-2b51a2db91fa.mp3', 47, '2026-06-12T13:11:29.007862', '2026-06-12T14:01:57.937079', N'Chào mừng các bạn đến với bài học về thành phần lập trình giao diện trong Java Swing. Trong bài học này, chúng ta sẽ tìm hiểu các thành phần cơ bản giúp xây dựng giao diện người dùng hiệu quả. Đầu tiên, ta có JFrame - cửa sổ chính của ứng dụng. Tiếp theo là JPanel, dùng để nhóm các thành phần lại với nhau. Các thành phần điều khiển như JButton, JLabel, JTextField sẽ giúp tương tác với người dùng. Ngoài ra, ta còn có các thành phần như JCheckBox, JRadioButton để lựa chọn, JComboBox để chọn từ danh sách. Cuối cùng, ta sẽ tìm hiểu cách bố trí các thành phần này bằng Layout Manager để giao diện đẹp và linh hoạt. Qua bài học, các bạn sẽ nắm được cách sử dụng các thành phần cơ bản để thiết kế giao diện trong Java Swing.', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u th\u00E0nh ph\u1EA7n giao di\u1EC7n Java Swing","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing window frame with interconnected nodes, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["JFrame - c\u1EEDa s\u1ED5 ch\u00EDnh","JPanel - nh\u00F3m th\u00E0nh ph\u1EA7n","C\u00E1c \u0111i\u1EC1u khi\u1EC3n c\u01A1 b\u1EA3n"],"SpeakerNotes":"Slide n\u00E0y gi\u1EDBi thi\u1EC7u t\u1ED5ng quan v\u1EC1 c\u00E1c th\u00E0nh ph\u1EA7n giao di\u1EC7n trong Java Swing, gi\u00FAp ng\u01B0\u1EDDi h\u1ECDc h\u00ECnh dung c\u1EA5u tr\u00FAc c\u01A1 b\u1EA3n c\u1EE7a m\u1ED9t \u1EE9ng d\u1EE5ng giao di\u1EC7n."},{"SlideNumber":2,"Title":"JFrame - C\u1EEDa s\u1ED5 ch\u00EDnh","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing rectangular frame symbolizing a window, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["L\u00E0 c\u1EEDa s\u1ED5 ch\u00EDnh c\u1EE7a \u1EE9ng d\u1EE5ng","Ch\u1EE9a c\u00E1c th\u00E0nh ph\u1EA7n giao di\u1EC7n kh\u00E1c","Qu\u1EA3n l\u00FD s\u1EF1 ki\u1EC7n c\u1EEDa s\u1ED5"],"SpeakerNotes":"JFrame l\u00E0 th\u00E0nh ph\u1EA7n quan tr\u1ECDng nh\u1EA5t, n\u00F3 t\u1EA1o ra c\u1EEDa s\u1ED5 ch\u00EDnh \u0111\u1EC3 ch\u1EE9a c\u00E1c th\u00E0nh ph\u1EA7n giao di\u1EC7n kh\u00E1c v\u00E0 x\u1EED l\u00FD c\u00E1c s\u1EF1 ki\u1EC7n li\u00EAn quan \u0111\u1EBFn c\u1EEDa s\u1ED5."},{"SlideNumber":3,"Title":"JPanel - Nh\u00F3m th\u00E0nh ph\u1EA7n","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing layered panels stacked, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["D\u00F9ng \u0111\u1EC3 nh\u00F3m c\u00E1c th\u00E0nh ph\u1EA7n","H\u1ED7 tr\u1EE3 b\u1ED1 tr\u00ED giao di\u1EC7n","T\u1EA1o c\u1EA5u tr\u00FAc r\u00F5 r\u00E0ng"],"SpeakerNotes":"JPanel gi\u00FAp nh\u00F3m c\u00E1c th\u00E0nh ph\u1EA7n l\u1EA1i v\u1EDBi nhau, h\u1ED7 tr\u1EE3 vi\u1EC7c b\u1ED1 tr\u00ED v\u00E0 t\u1ED5 ch\u1EE9c giao di\u1EC7n tr\u1EDF n\u00EAn r\u00F5 r\u00E0ng v\u00E0 d\u1EC5 qu\u1EA3n l\u00FD h\u01A1n."},{"SlideNumber":4,"Title":"C\u00E1c \u0111i\u1EC1u khi\u1EC3n c\u01A1 b\u1EA3n","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing buttons, sliders and text fields floating, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["JButton - n\u00FAt b\u1EA5m","JLabel - nh\u00E3n","JTextField - nh\u1EADp li\u1EC7u"],"SpeakerNotes":"C\u00E1c \u0111i\u1EC1u khi\u1EC3n c\u01A1 b\u1EA3n nh\u01B0 JButton, JLabel, JTextField gi\u00FAp ng\u01B0\u1EDDi d\u00F9ng t\u01B0\u01A1ng t\u00E1c v\u1EDBi \u1EE9ng d\u1EE5ng th\u00F4ng qua c\u00E1c n\u00FAt b\u1EA5m, nh\u00E3n hi\u1EC3n th\u1ECB v\u00E0 \u00F4 nh\u1EADp li\u1EC7u."},{"SlideNumber":5,"Title":"C\u00E1c th\u00E0nh ph\u1EA7n l\u1EF1a ch\u1ECDn","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing checkboxes and radio buttons interconnected, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["JCheckBox - h\u1ED9p ch\u1ECDn","JRadioButton - n\u00FAt ch\u1ECDn \u0111\u01A1n","JComboBox - danh s\u00E1ch ch\u1ECDn"],"SpeakerNotes":"C\u00E1c th\u00E0nh ph\u1EA7n l\u1EF1a ch\u1ECDn nh\u01B0 JCheckBox, JRadioButton v\u00E0 JComboBox gi\u00FAp ng\u01B0\u1EDDi d\u00F9ng ch\u1ECDn m\u1ED9t ho\u1EB7c nhi\u1EC1u t\u00F9y ch\u1ECDn trong giao di\u1EC7n."},{"SlideNumber":6,"Title":"Layout Manager - B\u1ED1 tr\u00ED giao di\u1EC7n","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing grid and flow patterns interconnected, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Qu\u1EA3n l\u00FD v\u1ECB tr\u00ED th\u00E0nh ph\u1EA7n","H\u1ED7 tr\u1EE3 giao di\u1EC7n linh ho\u1EA1t","C\u00E1c lo\u1EA1i Layout ph\u1ED5 bi\u1EBFn"],"SpeakerNotes":"Layout Manager gi\u00FAp qu\u1EA3n l\u00FD v\u1ECB tr\u00ED v\u00E0 k\u00EDch th\u01B0\u1EDBc c\u00E1c th\u00E0nh ph\u1EA7n trong giao di\u1EC7n, t\u1EA1o s\u1EF1 linh ho\u1EA1t v\u00E0 th\u1EA9m m\u1EF9 cho \u1EE9ng d\u1EE5ng."}]', N'{"EstimatedDurationMinutes":12,"Tone":"Th\u00E2n thi\u1EC7n, r\u00F5 r\u00E0ng, d\u1EC5 hi\u1EC3u","Pacing":"Ch\u1EADm v\u1EEBa ph\u