INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('ce7f8c8f-5340-4351-877f-40677c6dab4e', 'e3862898-0afb-4124-9ef0-89ea7878e4c4', N'Định nghĩa và phát triển TTNT', N'Khái niệm TTNT, sự phát triển và các loại TTNT.', 1, N'Định nghĩa TTNT; Lịch sử phát triển TTNT; Các loại TTNT cơ bản', N'/storage/video/ce7f8c8f-5340-4351-877f-40677c6dab4e.mp4', N'/storage/audio/ce7f8c8f-5340-4351-877f-40677c6dab4e.mp3', 53, '2026-06-12T15:27:03.595956', '2026-06-12T15:28:14.616091', N'Trí tuệ nhân tạo, hay còn gọi là TTNT, là lĩnh vực khoa học máy tính tập trung vào việc tạo ra các hệ thống có khả năng thực hiện các nhiệm vụ mà thông thường cần đến trí thông minh của con người. Những nhiệm vụ này bao gồm nhận dạng giọng nói, học hỏi, lập luận và giải quyết vấn đề.
