INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('c7e2f6e2-af8b-48b2-a2a5-453110e8d3b5', '308e2766-c732-4a7a-a926-cebf2e6eb284', N'TTNT trong sáng tạo nội dung', N'Ứng dụng TTNT trong sáng tạo nội dung số và truyền thông.', 4, N'TTNT sáng tạo nội dung; AI trong truyền thông', N'/storage/video/c7e2f6e2-af8b-48b2-a2a5-453110e8d3b5.mp4', N'/storage/audio/c7e2f6e2-af8b-48b2-a2a5-453110e8d3b5.mp3', 46, '2026-06-12T15:27:03.596103', '2026-06-12T15:42:38.398543', N'Trí tuệ nhân tạo đang mở ra những cơ hội mới trong lĩnh vực sáng tạo nội dung số, giúp tăng tốc và nâng cao chất lượng sản phẩm truyền thông.
INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('043b8c4b-3706-4fd4-af87-45dcad6e7196', '5d9b1662-8b9c-4ba5-ad65-273618ab982b', N'Đồng bộ hóa đa luồng', N'Kỹ thuật đồng bộ hóa trong lập trình đa luồng.', 5, N'Đồng bộ hóa đa luồng', N'/storage/video/043b8c4b-3706-4fd4-af87-45dcad6e7196.mp4', N'/storage/audio/043b8c4b-3706-4fd4-af87-45dcad6e7196.mp3', 53, '2026-06-12T13:11:29.007864', '2026-06-12T14:06:03.872462', N'Chào mừng các bạn đến với bài học về đồng bộ hóa đa luồng trong lập trình Java. Trong lập trình đa luồng, khi nhiều luồng cùng truy cập và thay đổi dữ liệu chung, sẽ xảy ra tình trạng tranh chấp tài nguyên, dẫn đến lỗi và kết quả không chính xác. Vì vậy, kỹ thuật đồng bộ hóa rất quan trọng để đảm bảo tính nhất quán và an toàn dữ liệu. Trong bài học này, chúng ta sẽ tìm hiểu các khái niệm cơ bản về đồng bộ hóa, các công cụ hỗ trợ trong Java như từ khóa synchronized, các khối synchronized, và các lớp hỗ trợ như Lock. Ngoài ra, chúng ta sẽ xem xét các ví dụ thực tế để hiểu cách áp dụng đồng bộ hóa hiệu quả, tránh tình trạng deadlock và cải thiện hiệu suất chương trình đa luồng.', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u v\u1EC1 \u0111\u1ED3ng b\u1ED9 h\u00F3a \u0111a lu\u1ED3ng","ImageKeyword":"Flat vector illustration, minimalist corporate style, a network of interconnected glowing threads converging into a single point, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["\u0110a lu\u1ED3ng l\u00E0 g\u00EC?","V\u1EA5n \u0111\u1EC1 tranh ch\u1EA5p t\u00E0i nguy\u00EAn","T\u1EA1i sao c\u1EA7n \u0111\u1ED3ng b\u1ED9 h\u00F3a"],"SpeakerNotes":"Slide n\u00E0y gi\u1EDBi thi\u1EC7u t\u1ED5ng quan v\u1EC1 \u0111a lu\u1ED3ng v\u00E0 nguy\u00EAn nh\u00E2n c\u1EA7n \u0111\u1ED3ng b\u1ED9 h\u00F3a. Khi nhi\u1EC1u lu\u1ED3ng c\u00F9ng truy c\u1EADp t\u00E0i nguy\u00EAn chung, n\u1EBFu kh\u00F4ng ki\u1EC3m so\u00E1t s\u1EBD g\u00E2y ra l\u1ED7i d\u1EEF li\u1EC7u."},{"SlideNumber":2,"Title":"Kh\u00E1i ni\u1EC7m \u0111\u1ED3ng b\u1ED9 h\u00F3a","ImageKeyword":"Flat vector illustration, minimalist corporate style, two gears interlocking and moving in harmony, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["\u0110\u1EA3m b\u1EA3o truy c\u1EADp tu\u1EA7n t\u1EF1","Ng\u0103n ch\u1EB7n xung \u0111\u1ED9t d\u1EEF li\u1EC7u","B\u1EA3o v\u1EC7 t\u00E0i nguy\u00EAn chung"],"SpeakerNotes":"\u0110\u1ED3ng b\u1ED9 h\u00F3a gi\u00FAp c\u00E1c lu\u1ED3ng truy c\u1EADp t\u00E0i nguy\u00EAn theo th\u1EE9 t\u1EF1, tr\u00E1nh xung \u0111\u1ED9t v\u00E0 \u0111\u1EA3m b\u1EA3o d\u1EEF li\u1EC7u kh\u00F4ng b\u1ECB h\u1ECFng."},{"SlideNumber":3,"Title":"T\u1EEB kh\u00F3a synchronized trong Java","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing lock symbol surrounded by flowing data streams, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Kh\u00F3a \u0111\u1ED1i t\u01B0\u1EE3ng ho\u1EB7c ph\u01B0\u01A1ng th\u1EE9c","Ch\u1EC9 cho ph\u00E9p m\u1ED9t lu\u1ED3ng truy c\u1EADp","\u0110\u01A1n gi\u1EA3n v\u00E0 hi\u1EC7u qu\u1EA3"],"SpeakerNotes":"T\u1EEB kh\u00F3a synchronized l\u00E0 c\u00E1ch \u0111\u01A1n gi\u1EA3n nh\u1EA5t \u0111\u1EC3 \u0111\u1ED3ng b\u1ED9 h\u00F3a trong Java, kh\u00F3a \u0111\u1ED1i t\u01B0\u1EE3ng ho\u1EB7c ph\u01B0\u01A1ng th\u1EE9c \u0111\u1EC3 ch\u1EC9 m\u1ED9t lu\u1ED3ng \u0111\u01B0\u1EE3c ph\u00E9p th\u1EF1c thi."},{"SlideNumber":4,"Title":"Kh\u1ED1i synchronized v\u00E0 ph\u01B0\u01A1ng th\u1EE9c synchronized","ImageKeyword":"Flat vector illustration, minimalist corporate style, overlapping transparent layers forming a protective shield, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Kh\u1ED1i synchronized gi\u1EDBi h\u1EA1n ph\u1EA1m vi","Ph\u01B0\u01A1ng th\u1EE9c synchronized kh\u00F3a to\u00E0n b\u1ED9 ph\u01B0\u01A1ng th\u1EE9c","L\u1EF1a ch\u1ECDn ph\u00F9 h\u1EE3p v\u1EDBi nhu c\u1EA7u"],"SpeakerNotes":"Kh\u1ED1i synchronized cho ph\u00E9p \u0111\u1ED3ng b\u1ED9 h\u00F3a trong ph\u1EA1m vi nh\u1ECF h\u01A1n, c\u00F2n ph\u01B0\u01A1ng th\u1EE9c synchronized kh\u00F3a to\u00E0n b\u1ED9 ph\u01B0\u01A1ng th\u1EE9c, gi\u00FAp ki\u1EC3m so\u00E1t linh ho\u1EA1t h\u01A1n."},{"SlideNumber":5,"Title":"L\u1EDBp Lock v\u00E0 c\u00E1c c\u00F4ng c\u1EE5 n\u00E2ng cao","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract digital hand holding a glowing key unlocking a complex mechanism, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Lock interface v\u00E0 ReentrantLock","H\u1ED7 tr\u1EE3 t\u00EDnh n\u0103ng n\u00E2ng cao","Qu\u1EA3n l\u00FD deadlock hi\u1EC7u qu\u1EA3"],"SpeakerNotes":"Java cung c\u1EA5p l\u1EDBp Lock v\u1EDBi nhi\u1EC1u t\u00EDnh n\u0103ng n\u00E2ng cao h\u01A1n synchronized, gi\u00FAp qu\u1EA3n l\u00FD \u0111\u1ED3ng b\u1ED9 ph\u1EE9c t\u1EA1p v\u00E0 tr\u00E1nh deadlock."},{"SlideNumber":6,"Title":"C\u00E1c l\u01B0u \u00FD khi \u0111\u1ED3ng b\u1ED9 h\u00F3a","ImageKeyword":"Flat vector illustration, minimalist corporate style, a balanced scale with glowing orbs on each side, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Tr\u00E1nh \u0111\u1ED3ng b\u1ED9 h\u00F3a qu\u00E1 m\u1EE9c","Gi\u1EA3m thi\u1EC3u th\u1EDDi gian gi\u1EEF kh\u00F3a","Ph\u00F2ng tr\u00E1nh deadlock"],"SpeakerNotes":"\u0110\u1ED3ng b\u1ED9 h\u00F3a c\u1EA7n \u0111\u01B0\u1EE3c s\u1EED d\u1EE5ng h\u1EE3p l\u00FD \u0111\u1EC3 tr\u00E1nh l\u00E0m gi\u1EA3m hi\u1