INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('0ba6c959-c830-43ca-b398-4efeed75ea41', '62a44281-4147-45b6-b674-b7a2c6ecff02', N'Môi trường Java', N'Giới thiệu môi trường phát triển Java.', 1, N'Môi trường Java', N'/storage/video/0ba6c959-c830-43ca-b398-4efeed75ea41.mp4', N'/storage/audio/0ba6c959-c830-43ca-b398-4efeed75ea41.mp3', 50, '2026-06-12T13:11:29.007834', '2026-06-12T13:24:21.135236', N'Chào mừng các bạn đến với bài học về Môi trường Java. Trong bài học này, chúng ta sẽ tìm hiểu về các thành phần chính của môi trường phát triển Java, bao gồm JDK, JRE và JVM. Các bạn sẽ hiểu rõ vai trò của từng phần và cách chúng phối hợp để chạy các ứng dụng Java. Ngoài ra, chúng ta cũng sẽ khám phá các công cụ hỗ trợ lập trình Java phổ biến, giúp các bạn có thể bắt đầu xây dựng ứng dụng một cách hiệu quả. Hãy cùng bắt đầu!', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u v\u1EC1 M\u00F4i tr\u01B0\u1EDDng Java","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing abstract network symbolizing interconnected software components, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["M\u00F4i tr\u01B0\u1EDDng Java g\u1ED3m nhi\u1EC1u th\u00E0nh ph\u1EA7n","H\u1ED7 tr\u1EE3 ph\u00E1t tri\u1EC3n v\u00E0 ch\u1EA1y \u1EE9ng d\u1EE5ng Java","T\u1EA1o n\u1EC1n t\u1EA3ng cho l\u1EADp tr\u00ECnh h\u01B0\u1EDBng \u0111\u1ED1i t\u01B0\u1EE3ng"],"SpeakerNotes":"Slide n\u00E0y gi\u1EDBi thi\u1EC7u t\u1ED5ng quan v\u1EC1 m\u00F4i tr\u01B0\u1EDDng Java, nh\u1EA5n m\u1EA1nh r\u1EB1ng n\u00F3 bao g\u1ED3m nhi\u1EC1u th\u00E0nh ph\u1EA7n kh\u00E1c nhau ph\u1ED1i h\u1EE3p \u0111\u1EC3 h\u1ED7 tr\u1EE3 ph\u00E1t tri\u1EC3n v\u00E0 ch\u1EA1y c\u00E1c \u1EE9ng d\u1EE5ng Java."},{"SlideNumber":2,"Title":"Java Development Kit (JDK)","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing toolkit with abstract tools floating above, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["B\u1ED9 c\u00F4ng c\u1EE5 ph\u00E1t tri\u1EC3n Java","Bao g\u1ED3m tr\u00ECnh bi\u00EAn d\u1ECBch, th\u01B0 vi\u1EC7n chu\u1EA9n","D\u00F9ng \u0111\u1EC3 vi\u1EBFt v\u00E0 bi\u00EAn d\u1ECBch m\u00E3 ngu\u1ED3n"],"SpeakerNotes":"JDK l\u00E0 b\u1ED9 c\u00F4ng c\u1EE5 ch\u00EDnh \u0111\u1EC3 ph\u00E1t tri\u1EC3n \u1EE9ng d\u1EE5ng Java, bao g\u1ED3m tr\u00ECnh bi\u00EAn d\u1ECBch v\u00E0 c\u00E1c th\u01B0 vi\u1EC7n c\u1EA7n thi\u1EBFt gi\u00FAp l\u1EADp tr\u00ECnh vi\u00EAn vi\u1EBFt v\u00E0 bi\u00EAn d\u1ECBch m\u00E3 ngu\u1ED3n."},{"SlideNumber":3,"Title":"Java Runtime Environment (JRE)","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing runtime engine with abstract gears turning smoothly, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["M\u00F4i tr\u01B0\u1EDDng ch\u1EA1y \u1EE9ng d\u1EE5ng Java","Ch\u1EE9a JVM v\u00E0 th\u01B0 vi\u1EC7n chu\u1EA9n","Ch\u1EC9 d\u00F9ng \u0111\u1EC3 ch\u1EA1y, kh\u00F4ng \u0111\u1EC3 ph\u00E1t tri\u1EC3n"],"SpeakerNotes":"JRE l\u00E0 m\u00F4i tr\u01B0\u1EDDng \u0111\u1EC3 ch\u1EA1y c\u00E1c \u1EE9ng d\u1EE5ng Java \u0111\u00E3 \u0111\u01B0\u1EE3c bi\u00EAn d\u1ECBch, bao g\u1ED3m JVM v\u00E0 c\u00E1c th\u01B0 vi\u1EC7n chu\u1EA9n, kh\u00F4ng d\u00F9ng \u0111\u1EC3 ph\u00E1t tri\u1EC3n m\u00E3 ngu\u1ED3n."},{"SlideNumber":4,"Title":"Java Virtual Machine (JVM)","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing virtual machine core with abstract circuits and light flows, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["M\u00E1y \u1EA3o Java","Ch\u1EA1y m\u00E3 bytecode Java","\u0110\u1EA3m b\u1EA3o t\u00EDnh \u0111\u1ED9c l\u1EADp n\u1EC1n t\u1EA3ng"],"SpeakerNotes":"JVM l\u00E0 th\u00E0nh ph\u1EA7n quan tr\u1ECDng gi\u00FAp ch\u1EA1y m\u00E3 bytecode Java tr\u00EAn nhi\u1EC1u n\u1EC1n t\u1EA3ng kh\u00E1c nhau, \u0111\u1EA3m b\u1EA3o t\u00EDnh \u0111\u1ED9c l\u1EADp v\u00E0 di \u0111\u1ED9ng c\u1EE7a \u1EE9ng d\u1EE5ng."},{"SlideNumber":5,"Title":"C\u00E1c c\u00F4ng c\u1EE5 h\u1ED7 tr\u1EE3 ph\u00E1t tri\u1EC3n Java","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract digital workspace with floating tools and code symbols, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["IDE nh\u01B0 Eclipse, IntelliJ IDEA","Tr\u00ECnh qu\u1EA3n l\u00FD d\u1EF1 \u00E1n Maven, Gradle","H\u1ED7 tr\u1EE3 vi\u1EBFt, bi\u00EAn d\u1ECBch, g\u1EE1 l\u1ED7i"],"SpeakerNotes":"Ngo\u00E0i JDK, c\u00E1c c\u00F4ng c\u1EE5 nh\u01B0 IDE v\u00E0 tr\u00ECnh qu\u1EA3n l\u00FD d\u1EF1 \u00E1n gi\u00FAp l\u1EADp tr\u00ECnh vi\u00EAn vi\u1EBFt m\u00E3, bi\u00EAn d\u1ECBch v\u00E0 g\u1EE1 l\u1ED7i hi\u1EC7u qu\u1EA3 h\u01A1n."},{"SlideNumber":6,"Title":"T\u00F3m t\u1EAFt v\u00E0 k\u1EBFt lu\u1EADn","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing summary icon with interconnected nodes forming a circle, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["M\u00F4i tr\u01B0\u1EDDng Java g\u1ED3m JDK, JRE, JVM","C\u00E1c c\u00F4ng c\u1EE5 h\u1ED7 tr\u1EE3 ph\u00E1t tri\u1EC3n r\u1EA5t quan tr\u1ECDng","Hi\u1EC3u r\u00F5 m\u00F4i tr\u01B0\u1EDDng gi\u00FAp l\u1EADp tr\u00ECnh hi\u1EC7u qu\u1EA3"],"SpeakerNotes":"T\u00F3m t\u1EAFt l\u1EA1i c\u00E1c th\u00E0nh ph\u1EA7n ch\u00EDnh c\u1EE7a m\u00F4i tr\u01B0\u1EDDng Java v\u00E0 nh\u1EA5n m\u1EA1nh t\u1EA7m quan tr\u1ECDng c\u1EE7a vi\u1EC7c hi\u1EC3u r\u00F5 m\u00F4i tr\u