INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('bcddbf60-518f-4040-9d93-721001955f14', 'eb5359ff-b4cf-4216-8347-cd4de08a0937', N'TTNT trong lĩnh vực Y tế', N'Ứng dụng TTNT trong chăm sóc sức khỏe và y tế.', 3, N'TTNT trong y tế; Chăm sóc sức khỏe', N'/storage/video/bcddbf60-518f-4040-9d93-721001955f14.mp4', N'/storage/audio/bcddbf60-518f-4040-9d93-721001955f14.mp3', 47, '2026-06-12T15:27:03.596099', '2026-06-12T15:36:28.067403', N'Trí tuệ nhân tạo đang tạo ra những bước tiến vượt bậc trong lĩnh vực y tế, giúp cải thiện chất lượng chăm sóc sức khỏe cho bệnh nhân trên toàn thế giới.
INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('253d6a4b-30a7-4e8e-8c9c-72d7a53ed00f', '471e02ee-fccf-40c5-a4cb-e2804c063086', N'.NET Framework là gì?', N'Giới thiệu các khái niệm cơ bản về .NET Framework và vai trò của nó trong phát triển ứng dụng.', 1, N'Khái niệm .NET Framework, lịch sử, mục đích sử dụng.', NULL, NULL, NULL, '2026-06-17T08:42:15.944144', NULL, N'Chào mừng các bạn đến với bài học đầu tiên của học phần Lập trình trên môi trường Windows. Trong bài học này, chúng ta sẽ cùng tìm hiểu về một khái niệm rất quan trọng, đó là .NET Framework. Đây là nền tảng cốt lõi cho việc phát triển ứng dụng trên Windows mà chúng ta sẽ học.
INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('e125b3e1-ca3a-4cc0-8dc0-745f4297019d', 'cad5ffa7-35aa-42a7-9ed5-e47d94546bd9', N'Khái niệm lớp trừu tượng', N'Định nghĩa và vai trò của lớp trừu tượng.', 1, N'Khái niệm lớp trừu tượng', N'/storage/video/e125b3e1-ca3a-4cc0-8dc0-745f4297019d.mp4', N'/storage/audio/e125b3e1-ca3a-4cc0-8dc0-745f4297019d.mp3', 44, '2026-06-12T13:11:29.007846', '2026-06-12T13:44:27.117289', N'Chào mừng các bạn đến với bài học về khái niệm lớp trừu tượng trong lập trình hướng đối tượng. Trong bài học này, chúng ta sẽ tìm hiểu định nghĩa lớp trừu tượng, vai trò và tầm quan trọng của nó trong thiết kế phần mềm. Lớp trừu tượng là một lớp không thể khởi tạo đối tượng trực tiếp mà chỉ dùng làm khuôn mẫu cho các lớp con kế thừa. Nó giúp ta định nghĩa các phương thức chung mà các lớp con phải triển khai, từ đó tăng tính linh hoạt và mở rộng của chương trình. Qua bài học, các bạn sẽ hiểu rõ hơn về cách sử dụng lớp trừu tượng trong Java để thiết kế ứng dụng hiệu quả hơn.', N'[{"SlideNumber":1,"Title":"\u0110\u1ECBnh ngh\u0129a l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing abstract shape representing a blueprint or framework, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["L\u1EDBp kh\u00F4ng th\u1EC3 t\u1EA1o \u0111\u1ED1i t\u01B0\u1EE3ng tr\u1EF1c ti\u1EBFp","Ch\u1EE9a c\u00E1c ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng v\u00E0 c\u1EE5 th\u1EC3","L\u00E0m khu\u00F4n m\u1EABu cho c\u00E1c l\u1EDBp con"],"SpeakerNotes":"Slide n\u00E0y gi\u1EDBi thi\u1EC7u \u0111\u1ECBnh ngh\u0129a c\u01A1 b\u1EA3n c\u1EE7a l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng. L\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng kh\u00F4ng th\u1EC3 \u0111\u01B0\u1EE3c kh\u1EDFi t\u1EA1o th\u00E0nh \u0111\u1ED1i t\u01B0\u1EE3ng m\u00E0 ch\u1EC9 d\u00F9ng \u0111\u1EC3 \u0111\u1ECBnh ngh\u0129a c\u00E1c ph\u01B0\u01A1ng th\u1EE9c m\u00E0 c\u00E1c l\u1EDBp con ph\u1EA3i th\u1EF1c hi\u1EC7n. N\u00F3 c\u00F3 th\u1EC3 ch\u1EE9a c\u1EA3 ph\u01B0\u01A1ng th\u1EE9c \u0111\u00E3 c\u00E0i \u0111\u1EB7t v\u00E0 ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng ch\u01B0a c\u00F3 ph\u1EA7n th\u00E2n."},{"SlideNumber":2,"Title":"Vai tr\u00F2 c\u1EE7a l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng","ImageKeyword":"Flat vector illustration, minimalist corporate style, interconnected abstract shapes symbolizing hierarchy and inheritance, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["\u0110\u1ECBnh ngh\u0129a chu\u1EA9n chung cho c\u00E1c l\u1EDBp con","T\u0103ng t\u00EDnh m\u1EDF r\u1ED9ng v\u00E0 b\u1EA3o tr\u00EC","H\u1ED7 tr\u1EE3 \u0111a h\u00ECnh trong l\u1EADp tr\u00ECnh"],"SpeakerNotes":"L\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng gi\u00FAp \u0111\u1ECBnh ngh\u0129a m\u1ED9t chu\u1EA9n chung cho c\u00E1c l\u1EDBp con, \u0111\u1EA3m b\u1EA3o c\u00E1c l\u1EDBp n\u00E0y c\u00F3 c\u00E1c ph\u01B0\u01A1ng th\u1EE9c c\u1EA7n thi\u1EBFt. \u0110i\u1EC1u n\u00E0y gi\u00FAp ch\u01B0\u01A1ng tr\u00ECnh d\u1EC5 d\u00E0ng m\u1EDF r\u1ED9ng v\u00E0 b\u1EA3o tr\u00EC h\u01A1n, \u0111\u1ED3ng th\u1EDDi h\u1ED7 tr\u1EE3 t\u00EDnh \u0111a h\u00ECnh trong l\u1EADp tr\u00ECnh h\u01B0\u1EDBng \u0111\u1ED1i t\u01B0\u1EE3ng."},{"SlideNumber":3,"Title":"T\u00EDnh ch\u1EA5t c\u1EE7a l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng trong Java","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing layers symbolizing abstraction and encapsulation, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["C\u00F3 th\u1EC3 ch\u1EE9a ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng v\u00E0 ph\u01B0\u01A1ng th\u1EE9c th\u01B0\u1EDDng","Kh\u00F4ng th\u1EC3 t\u1EA1o \u0111\u1ED1i t\u01B0\u1EE3ng tr\u1EF1c ti\u1EBFp","L\u1EDBp con ph\u1EA3i tri\u1EC3n khai ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng"],"SpeakerNotes":"Trong Java, l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng c\u00F3 th\u1EC3 ch\u1EE9a c\u1EA3 ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng v\u00E0 ph\u01B0\u01A1ng th\u1EE9c \u0111\u00E3 c\u00E0i \u0111\u1EB7t. B\u1EA1n kh\u00F4ng th\u1EC3 t\u1EA1o \u0111\u1ED1i t\u01B0\u1EE3ng t\u1EEB l\u1EDBp n\u00E0y tr\u1EF1c ti\u1EBFp m\u00E0 ph\u1EA3i th\u00F4ng qua l\u1EDBp con. C\u00E1c l\u1EDBp con k\u1EBF th\u1EEBa b\u1EAFt bu\u1ED9c ph\u1EA3i tri\u1EC3n khai c\u00E1c ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng \u0111\u1EC3 ho\u00E0n ch\u1EC9nh ch\u1EE9c n\u0103ng."}]', N'{"EstimatedDurationMinutes":7,"Tone":"truy\u1EC1n c\u1EA3m, th\u00E2n thi\u1EC7n, r\u00F5 r\u00E0ng","Pacing":"v\u1EEBa ph\u1EA3i, c\u00F3 nh\u1EA5n nh\u00E1 \u0111\u1EC3 ng\u01B0\u1EDDi h\u1ECDc d\u1EC5 ti\u1EBFp thu","TargetAudience":"sinh vi\u00EAn \u0111\u1EA1i h\u1ECDc ng\u00E0nh c\u00F4ng ngh\u1EC7 th\u00F4ng tin, m\u1EDBi b\u1EAFt \u0111\u1EA7u h\u1ECDc l\u1EADp tr\u00ECnh h\u01B0\u1EDBng \u0111\u1ED1i t\u01B0\u1EE3ng","PronunciationNotes":"ph\u00E1t \u00E2m r\u00F5 r\u00E0ng c\u00E1c thu\u1EADt ng\u1EEF chuy\u00EAn ng\u00E0nh nh\u01B0 \u0027l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng\u0027, \u0027ph\u01B0\u01A1ng th\u1EE9c\u0027, \u0027\u0111a h\u00ECnh\u0027, \u0027k\u1EBF th\u1EEBa\u0027, tr\u00E1nh n\u00F3i nhanh qu\u00E1 g\u00E2y kh\u00F3 hi\u1EC3u"}', N'Completed', '2026-06-12T13:43:28.613906', NULL, N'[{"SlideNumber":1,"Title":"\u0110\u1ECBnh ngh\u0129a l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng","NarrationText":"Slide n\u00E0y gi\u1EDBi thi\u1EC7u \u0111\u1ECBnh ngh\u0129a c\u01A1 b\u1EA3n c\u1EE7a l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng. L\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng kh\u00F4ng th\u1EC3 \u0111\u01B0\u1EE3c kh\u1EDFi t\u1EA1o th\u00E0nh \u0111\u1ED1i t\u01B0\u1EE3ng m\u00E0 ch\u1EC9 d\u00F9ng \u0111\u1EC3 \u0111\u1ECBnh ngh\u0129a c\u00E1c ph\u01B0\u01A1ng th\u1EE9c m\u00E0 c\u00E1c l\u1EDBp con ph\u1EA3i th\u1EF1c hi\u1EC7n. N\u00F3 c\u00F3 th\u1EC3 ch\u1EE9a c\u1EA3 ph\u01B0\u01A1ng th\u1EE9c \u0111\u00E3 c\u00E0i \u0111\u1EB7t v\u00E0 ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng ch\u01B0a c\u00F3 ph\u1EA7n th\u00E2n.","AudioUrl":"/storage/audio/e125b3e1-ca3a-4cc0-8dc0-745f4297019d-slide-1.mp3","DurationSeconds":15.36},{"SlideNumber":2,"Title":"Vai tr\u00F2 c\u1EE7a l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng","NarrationText":"L\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng gi\u00FAp \u0111\u1ECBnh ngh\u0129a m\u1ED9t chu\u1EA9n chung cho c\u00E1c l\u1EDBp con, \u0111\u1EA3m b\u1EA3o c\u00E1c l\u1EDBp n\u00E0y c\u00F3 c\u00E1c ph\u01B0\u01A1ng th\u1EE9c c\u1EA7n thi\u1EBFt. \u0110i\u1EC1u n\u00E0y gi\u00FAp ch\u01B0\u01A1ng tr\u00ECnh d\u1EC5 d\u00E0ng m\u1EDF r\u1ED9ng v\u00E0 b\u1EA3o tr\u00EC h\u01A1n, \u0111\u1ED3ng th\u1EDDi h\u1ED7 tr\u1EE3 t\u00EDnh \u0111a h\u00ECnh trong l\u1EADp tr\u00ECnh h\u01B0\u1EDBng \u0111\u1ED1i t\u01B0\u1EE3ng.","AudioUrl":"/storage/audio/e125b3e1-ca3a-4cc0-8dc0-745f4297019d-slide-2.mp3","DurationSeconds":13.08},{"SlideNumber":3,"Title":"T\u00EDnh ch\u1EA5t c\u1EE7a l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng trong Java","NarrationText":"Trong Java, l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng c\u00F3 th\u1EC3 ch\u1EE9a c\u1EA3 ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng v\u00E0 ph\u01B0\u01A1ng th\u1EE9c \u0111\u00E3 c\u00E0i \u0111\u1EB7t. B\u1EA1n kh\u00F4ng th\u1EC3 t\u1EA1o \u0111\u1ED1i t\u01B0\u1EE3ng t\u1EEB l\u1EDBp n\u00E0y tr\u1EF1c ti\u1EBFp m\u00E0 ph\u1EA3i th\u00F4ng qua l\u1EDBp con. C\u00E1c l\u1EDBp con k\u1EBF th\u1EEBa b\u1EAFt bu\u1ED9c ph\u1EA3i tri\u1EC3n khai c\u00E1c ph\u01B0\u01A1ng th\u1EE9c tr\u1EEBu t\u01B0\u1EE3ng \u0111\u1EC3 ho\u00E0n ch\u1EC9nh ch\u1EE9c n\u0103ng.","AudioUrl":"/storage/audio/e125b3e1-ca3a-4cc0-8dc0-745f4297019d-slide-3.mp3","DurationSeconds":15.36}]', N'Completed', NULL, '2026-06-12T13:44:22.589919', N'Completed', NULL, '2026-06-12T13:44:27.117289', NULL, NULL, NULL, NULL, NULL, NULL, 1);
INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('2b83feb9-72a8-408e-9490-74fd304c3381', '440378dd-42a8-420d-a977-d6c957353bc3', N'Lớp, thể hiện, biến đối tượng, thông điệp', N'Định nghĩa và vai trò của lớp, thể hiện, biến đối tượng và thông điệp.', 2, N'Lớp, thể hiện, biến đối tượng, thông điệp', N'/storage/video/2b83feb9-72a8-408e-9490-74fd304c3381.mp4', N'/storage/audio/2b83feb9-72a8-408e-9490-74fd304c3381.mp3', 36, '2026-06-12T13:11:29.007831', '2026-06-12T13:19:04.972250', N'Chào mừng các bạn đến với bài học hôm nay về các khái niệm cơ bản trong lập trình hướng đối tượng. Trong bài học này, chúng ta sẽ tìm hiểu về lớp, thể hiện, biến đối tượng và thông điệp - những thành phần cốt lõi giúp xây dựng các ứng dụng theo mô hình hướng đối tượng. Đầu tiên, lớp là khuôn mẫu để tạo ra các đối tượng, định nghĩa các thuộc tính và phương thức chung. Thể hiện là một đối tượng cụ thể được tạo ra từ lớp. Biến đối tượng là biến dùng để tham chiếu đến thể hiện đó. Cuối cùng, thông điệp là cách các đối tượng giao tiếp với nhau thông qua việc gọi phương thức. Hiểu rõ các khái niệm này sẽ giúp bạn thiết kế và xây dựng phần mềm hiệu quả hơn. Bây giờ, chúng ta sẽ đi sâu vào từng khái niệm một cách chi tiết.', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u v\u1EC1 L\u1EADp tr\u00ECnh h\u01B0\u1EDBng \u0111\u1ED1i t\u01B0\u1EE3ng","ImageKeyword":"Flat vector illustration, minimalist corporate style, a g