INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('84261e76-29e5-441c-8ed9-7c1d1d641d06', '877de1ba-7d51-47e4-a870-fb2b345dceca', N'Tạo layout cho một window', N'Tìm hiểu các panel layout khác nhau và cách tạo layout cho cửa sổ WPF.', 2, N'Grid, StackPanel, DockPanel, WrapPanel, Canvas.', NULL, NULL, NULL, '2026-06-17T08:42:15.944628', NULL, NULL, NULL, NULL, N'Failed', '2026-06-17T08:43:44.853184', N'A task was canceled.', NULL, N'NotGenerated', NULL, NULL, N'NotGenerated', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1);
INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('146830f0-d114-4a2d-9f4d-7d68154fa5f9', '98c4f99f-8800-4278-a885-cf6d4b0a2be8', N'Tự định nghĩa Exception', N'Tạo và sử dụng ngoại lệ tùy chỉnh trong Java.', 4, N'Tự định nghĩa Exception', N'/storage/video/146830f0-d114-4a2d-9f4d-7d68154fa5f9.mp4', N'/storage/audio/146830f0-d114-4a2d-9f4d-7d68154fa5f9.mp3', 47, '2026-06-12T13:11:29.007853', '2026-06-12T13:50:52.109978', N'Chào mừng các bạn đến với bài học hôm nay về cách tự định nghĩa Exception trong Java. Trong lập trình, ngoại lệ giúp chúng ta xử lý các tình huống lỗi một cách linh hoạt và có kiểm soát. Tuy nhiên, đôi khi các ngoại lệ có sẵn không đáp ứng đủ yêu cầu của ứng dụng. Vì vậy, Java cho phép chúng ta tạo ra các ngoại lệ tùy chỉnh để phù hợp với logic nghiệp vụ riêng. Trong bài học này, chúng ta sẽ tìm hiểu cách tạo lớp ngoại lệ mới kế thừa từ Exception hoặc RuntimeException, cách sử dụng các constructor để truyền thông điệp lỗi, và cách bắt và xử lý các ngoại lệ này trong chương trình. Qua đó, bạn sẽ nâng cao khả năng quản lý lỗi và làm cho mã nguồn trở nên rõ ràng, dễ bảo trì hơn.', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u v\u1EC1 Exception t\u00F9y ch\u1EC9nh","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing puzzle pieces connecting smoothly, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Ngo\u1EA1i l\u1EC7 t\u00F9y ch\u1EC9nh l\u00E0 g\u00EC?","T\u1EA1i sao c\u1EA7n t\u1EA1o Exception ri\u00EAng?","L\u1EE3i \u00EDch khi s\u1EED d\u1EE5ng Exception t\u00F9y ch\u1EC9nh"],"SpeakerNotes":"Slide n\u00E0y gi\u00FAp h\u1ECDc vi\u00EAn hi\u1EC3u kh\u00E1i ni\u1EC7m c\u01A1 b\u1EA3n v\u1EC1 Exception t\u00F9y ch\u1EC9nh v\u00E0 l\u00FD do t\u1EA1i sao ch\u00FAng ta c\u1EA7n t\u1EA1o ra c\u00E1c ngo\u1EA1i l\u1EC7 ri\u00EAng bi\u1EC7t \u0111\u1EC3 x\u1EED l\u00FD c\u00E1c t\u00ECnh hu\u1ED1ng \u0111\u1EB7c th\u00F9 trong \u1EE9ng d\u1EE5ng."},{"SlideNumber":2,"Title":"C\u00E1ch t\u1EA1o l\u1EDBp Exception m\u1EDBi","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing shield symbolizing protection and control, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["K\u1EBF th\u1EEBa t\u1EEB Exception ho\u1EB7c RuntimeException","\u0110\u1ECBnh ngh\u0129a constructor ph\u00F9 h\u1EE3p","Ghi \u0111\u00E8 ph\u01B0\u01A1ng th\u1EE9c n\u1EBFu c\u1EA7n"],"SpeakerNotes":"Tr\u00ECnh b\u00E0y c\u00E1ch khai b\u00E1o m\u1ED9t l\u1EDBp ngo\u1EA1i l\u1EC7 m\u1EDBi trong Java, bao g\u1ED3m vi\u1EC7c k\u1EBF th\u1EEBa t\u1EEB l\u1EDBp Exception ho\u1EB7c RuntimeException, v\u00E0 c\u00E1ch \u0111\u1ECBnh ngh\u0129a c\u00E1c constructor \u0111\u1EC3 truy\u1EC1n th\u00F4ng tin l\u1ED7i."},{"SlideNumber":3,"Title":"S\u1EED d\u1EE5ng Exception t\u00F9y ch\u1EC9nh trong m\u00E3 ngu\u1ED3n","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing pathway with branching points, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["N\u00E9m ngo\u1EA1i l\u1EC7 b\u1EB1ng t\u1EEB kh\u00F3a throw","B\u1EAFt ngo\u1EA1i l\u1EC7 b\u1EB1ng try-catch","X\u1EED l\u00FD l\u1ED7i theo logic nghi\u1EC7p v\u1EE5"],"SpeakerNotes":"Gi\u1EA3i th\u00EDch c\u00E1ch s\u1EED d\u1EE5ng Exception t\u00F9y ch\u1EC9nh trong ch\u01B0\u01A1ng tr\u00ECnh: n\u00E9m ngo\u1EA1i l\u1EC7 khi ph\u00E1t hi\u1EC7n l\u1ED7i, b\u1EAFt v\u00E0 x\u1EED l\u00FD ngo\u1EA1i l\u1EC7 trong kh\u1ED1i try-catch \u0111\u1EC3 \u0111\u1EA3m b\u1EA3o ch\u01B0\u01A1ng tr\u00ECnh ho\u1EA1t \u0111\u1ED9ng \u1ED5n \u0111\u1ECBnh."},{"SlideNumber":4,"Title":"V\u00ED d\u1EE5 minh h\u1ECDa","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing lightbulb symbolizing idea and clarity, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["T\u1EA1o l\u1EDBp ngo\u1EA1i l\u1EC7 InvalidAgeException","N\u00E9m ngo\u1EA1i l\u1EC7 khi tu\u1ED5i kh\u00F4ng h\u1EE3p l\u1EC7","B\u1EAFt v\u00E0 x\u1EED l\u00FD ngo\u1EA1i l\u1EC7 trong main"],"SpeakerNotes":"Cung c\u1EA5p v\u00ED d\u1EE5 c\u1EE5 th\u1EC3 v\u1EC1 vi\u1EC7c t\u1EA1o v\u00E0 s\u1EED d\u1EE5ng Exception t\u00F9y ch\u1EC9nh trong Java, gi\u00FAp h\u1ECDc vi\u00EAn d\u1EC5 d\u00E0ng h\u00ECnh dung v\u00E0 \u00E1p d\u1EE5ng v\u00E0o th\u1EF1c t\u1EBF."},{"SlideNumber":5,"Title":"T\u00F3m t\u1EAFt v\u00E0 l\u01B0u \u00FD","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing checklist with ticks, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Exception t\u00F9y ch\u1EC9nh gi\u00FAp qu\u1EA3n l\u00FD l\u1ED7i hi\u1EC7u qu\u1EA3","N\u00EAn \u0111\u1EB7t t\u00EAn r\u00F5 r\u00E0ng, d\u1EC5 hi\u1EC3u","S\u1EED d\u1EE5ng h\u1EE3p l\u00FD \u0111\u1EC3 t\u0103ng t\u00EDnh b\u1EA3o tr\u00EC m\u00E3"],"SpeakerNotes":"T\u1ED5ng k\u1EBFt l\u1EA1i c\u00E1c \u0111i\u1EC3m ch\u00EDnh c\u1EE7a b\u00E0i h\u1ECDc, nh\u1EA5n m\u1EA1nh c\u00E1c l\u01B0u \u00FD quan tr\u1ECDng khi t\u1EA1o v\u00E0 s\u1EED d\u1EE5ng Exception t\u00F9y ch\u1EC9nh \u0111\u1EC3 \u0111\u1EA3m b\u1EA3o m\u00E3 ngu\u1ED3n ch\u1EA5t l\u01B0\u1EE3ng v\u00E0 d\u1EC5 d\u00E0ng b\u1EA3o tr\u00EC."}]', N'{"EstimatedDurationMinutes":12,"Tone":"Th\u00E2n thi\u1EC7n, r\u00F5 r\u00E0ng, chuy\u00EAn nghi\u1EC7p","Pacing":"Ch\u1EADm v\u1EEBa ph\u1EA3i, d\u1EC5 theo d\u00F5i","TargetAudience":"Sinh vi\u00EAn \u0111\u1EA1i h\u1ECDc ng\u00E0nh c\u00F4ng ngh\u1EC7 th\u00F4ng tin, l\u1EADp tr\u00ECnh vi\u00EAn m\u1EDBi h\u1ECDc Java","PronunciationNotes":"Ph\u00E1t \u00E2m r\u00F5 r\u00E0ng c\u00E1c thu\u1EADt ng\u1EEF chuy\u00EAn ng\u00E0nh nh\u01B0 Exception, constructor, try-catch, RuntimeException; tr\u00E1nh n\u00F3i nhanh \u0111\u1EC3 ng\u01B0\u1EDDi nghe d\u1EC5 hi\u1EC3u"}', N'Completed', '2026-06-12T13:50:15.293664', NULL, N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u v\u1EC1 Exception t\u00F9y ch\u1EC9nh","NarrationText":"Slide n\u00E0y gi\u00FAp h\u1ECDc vi\u00EAn hi\u1EC3u kh\u00E1i ni\u1EC7m c\u01A1 b\u1EA3n v\u1EC1 Exception t\u00F9y ch\u1EC9nh v\u00E0 l\u00FD do t\u1EA1i sao ch\u00FAng ta c\u1EA7n t\u1EA1o ra c\u00E1c ngo\u1EA1i l\u1EC7 ri\u00EAng bi\u1EC7t \u0111\u1EC3 x\u1EED l\u00FD c\u00E1c t\u00ECnh hu\u1ED1ng \u0111\u1EB7c th\u00F9 trong \u1EE9ng d\u1EE5ng.","AudioUrl":"/storage/audio/146830f0-d114-4a2d-9f4d-7d68154fa5f9-slide-1.mp3","DurationSeconds":9.624},{"SlideNumber":2,"Title":"C\u00E1ch t\u1EA1o l\u1EDBp Exception m\u1EDBi","NarrationText":"Tr\u00ECnh b\u00E0y c\u00E1ch khai b\u00E1o m\u1ED9t l\u1EDBp ngo\u1EA1i l\u1EC7 m\u1EDBi trong Java, bao g\u1ED3m vi\u1EC7c k\u1EBF th\u1EEBa t\u1EEB l\u1EDBp Exception ho\u1EB7c RuntimeException, v\u00E0 c\u00E1ch \u0111\u1ECBnh ngh\u0129a c\u00E1c constructor \u0111\u1EC3 truy\u1EC1n th\u00F4ng tin l\u1ED7i.","AudioUrl":"/storage/audio/146830f0-d114-4a2d-9f4d-7d68154fa5f9-slide-2.mp3","DurationSeconds":10.008},{"SlideNumber":3,"Title":"S\u1EED d\u1EE5ng Exception t\u00F9y ch\u1EC9nh trong m\u00E3 ngu\u1ED3n","NarrationText":"Gi\u1EA3i th\u00EDch c\u00E1ch s\u1EED d\u1EE5ng Exception t\u00F9y ch\u1EC9nh trong ch\u01B0\u01A1ng tr\u00ECnh: n\u00E9m ngo\u1EA1i l\u1EC7 khi ph\u00E1t hi\u1EC7n l\u1ED7i, b\u1EAFt v\u00E0 x\u1EED l\u00FD ngo\u1EA1i l\u1EC7 trong kh\u1ED1i try-catch \u0111\u1EC3 \u0111\u1EA3m b\u1EA3o ch\u01B0\u01A1ng tr\u00ECnh ho\u1EA1t \u0111\u1ED9ng \u1ED5n \u0111\u1ECBnh.","AudioUrl":"/storage/audio/146830f0-d114-4a2d-9f4d-7d68154fa5f