INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('d6794883-b731-48b7-975e-88ec07eb3963', '35efa6cd-f86b-4ec0-8a31-da893ac115c8', N'Phân cấp kế thừa', N'Cấu trúc phân cấp kế thừa trong Java.', 4, N'Phân cấp kế thừa', N'/storage/video/d6794883-b731-48b7-975e-88ec07eb3963.mp4', N'/storage/audio/d6794883-b731-48b7-975e-88ec07eb3963.mp3', 53, '2026-06-12T13:11:29.007845', '2026-06-12T13:40:33.905177', N'Chào mừng các bạn đến với bài học hôm nay về phân cấp kế thừa trong Java. Trong lập trình hướng đối tượng, kế thừa cho phép chúng ta tạo ra các lớp con từ lớp cha, giúp tái sử dụng mã nguồn và mở rộng chức năng một cách hiệu quả. Phân cấp kế thừa là cấu trúc tổ chức các lớp theo dạng cây, trong đó mỗi lớp con kế thừa thuộc tính và phương thức từ lớp cha của nó. Qua bài học này, chúng ta sẽ tìm hiểu cách xây dựng phân cấp kế thừa, cách hoạt động của nó và những lưu ý quan trọng khi thiết kế phân cấp kế thừa trong Java. Hãy cùng bắt đầu!', N'[{"SlideNumber":1,"Title":"Kh\u00E1i ni\u1EC7m ph\u00E2n c\u1EA5p k\u1EBF th\u1EEBa","ImageKeyword":"Flat vector illustration, minimalist corporate style, a branching tree structure with glowing nodes representing inheritance hierarchy, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["K\u1EBF th\u1EEBa l\u00E0 t\u1EA1o l\u1EDBp con t\u1EEB l\u1EDBp cha","Ph\u00E2n c\u1EA5p k\u1EBF th\u1EEBa l\u00E0 t\u1ED5 ch\u1EE9c l\u1EDBp theo d\u1EA1ng c