INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('5b4d32a4-eccd-4f11-b1e4-8aa6af208997', '5d9b1662-8b9c-4ba5-ad65-273618ab982b', N'Xử lý sự kiện', N'Cơ chế xử lý sự kiện trong giao diện người dùng.', 2, N'Xử lý sự kiện', N'/storage/video/5b4d32a4-eccd-4f11-b1e4-8aa6af208997.mp4', N'/storage/audio/5b4d32a4-eccd-4f11-b1e4-8aa6af208997.mp3', 35, '2026-06-12T13:11:29.007862', '2026-06-12T14:02:52.280987', N'Chào mừng các bạn đến với bài học về xử lý sự kiện trong lập trình giao diện người dùng. Trong bài học này, chúng ta sẽ tìm hiểu cơ chế xử lý sự kiện, cách các sự kiện được phát hiện và phản hồi trong ứng dụng Java. Đầu tiên, sự kiện là gì? Sự kiện là các hành động hoặc thay đổi trạng thái do người dùng hoặc hệ thống tạo ra, ví dụ như nhấn nút, di chuyển chuột, hoặc thay đổi dữ liệu. Tiếp theo, chúng ta sẽ xem xét cách Java xử lý các sự kiện này thông qua các listener - các đối tượng lắng nghe và phản hồi sự kiện. Chúng ta cũng sẽ tìm hiểu cách đăng ký listener với các thành phần giao diện để nhận sự kiện. Cuối cùng, bài học sẽ hướng dẫn cách viết mã xử lý sự kiện đơn giản, giúp ứng dụng tương tác hiệu quả với người dùng. Hãy cùng bắt đầu!', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u v\u1EC1 s\u1EF1 ki\u1EC7n trong giao di\u1EC7n ng\u01B0\u1EDDi d\u00F9ng","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract glowing nodes connected by lines representing in