INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('ffa1f815-9c5a-4692-b25f-8cd59b8a2ba2', 'cad5ffa7-35aa-42a7-9ed5-e47d94546bd9', N'Hiện thực lớp và phương thức trừu tượng', N'Cách hiện thực lớp và phương thức trừu tượng.', 2, N'Hiện thực lớp và phương thức trừu tượng', N'/storage/video/ffa1f815-9c5a-4692-b25f-8cd59b8a2ba2.mp4', N'/storage/audio/ffa1f815-9c5a-4692-b25f-8cd59b8a2ba2.mp3', 49, '2026-06-12T13:11:29.007847', '2026-06-12T13:45:27.854870', N'Chào mừng các bạn đến với bài học hôm nay về hiện thực lớp và phương thức trừu tượng trong lập trình hướng đối tượng với Java. Trong bài học này, chúng ta sẽ tìm hiểu cách khai báo và triển khai các lớp trừu tượng, cũng như cách hiện thực các phương thức trừu tượng để xây dựng các ứng dụng linh hoạt và mở rộng. Đầu tiên, chúng ta sẽ xem xét khái niệm lớp trừu tượng và vai trò của nó trong thiết kế phần mềm. Tiếp theo, chúng ta sẽ học cách định nghĩa phương thức trừu tượng và cách lớp con hiện thực các phương thức này. Cuối cùng, chúng ta sẽ cùng nhau xem ví dụ minh họa cụ thể để hiểu rõ hơn về cách áp dụng trong thực tế. Hãy bắt đầu!', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u l\u1EDBp tr\u1EEBu t\u01B0\u1EE3ng","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing abstract shield symbolizing protection and abstraction, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["L\u1EDBp tr\u1EEBu t\u