INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('c689f0fb-7af8-4a5d-8633-b0759a40b60a', '98c4f99f-8800-4278-a885-cf6d4b0a2be8', N'Cơ chế gom rác (Garbage Collection)', N'Cơ chế thu hồi bộ nhớ tự động trong Java.', 5, N'Cơ chế gom rác', N'/storage/video/c689f0fb-7af8-4a5d-8633-b0759a40b60a.mp4', N'/storage/audio/c689f0fb-7af8-4a5d-8633-b0759a40b60a.mp3', 41, '2026-06-12T13:11:29.007853', '2026-06-12T13:51:38.789640', N'Chào mừng các bạn đến với bài học về cơ chế gom rác trong Java. Trong lập trình, việc quản lý bộ nhớ là rất quan trọng để đảm bảo ứng dụng hoạt động hiệu quả và ổn định. Java sử dụng cơ chế gom rác để tự động thu hồi bộ nhớ không còn sử dụng, giúp lập trình viên không phải lo lắng về việc giải phóng bộ nhớ thủ công. Trong bài học này, chúng ta sẽ tìm hiểu nguyên lý hoạt động của cơ chế gom rác, các thuật toán phổ biến và cách Java thực hiện thu hồi bộ nhớ tự động. Qua đó, các bạn sẽ hiểu rõ hơn về cách Java quản lý tài nguyên và tối ưu hiệu suất ứng dụng.', N'[{"SlideNumber":1,"Title":"Gi\u1EDBi thi\u1EC7u c\u01A1 ch\u1EBF gom r\u00E1c","ImageKeyword":"Flat vector illustration, minimalist corporate style, a glowing network of interconnected nodes representing memory blocks, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Qu\u1EA3n l\u00FD b\u1ED9 nh\u1EDB t\u1EF1 \u0111\u1ED9ng trong Java","Gi\u00FAp thu h\u1ED3i b\u1ED9 nh\u1EDB kh\u00F4ng c\u00F2n s\u1EED d\u1EE5ng","Gi\u1EA3m thi\u1EC3u l\u1ED7i tr\u00E0n b\u1ED9 nh\u1EDB"],"SpeakerNotes":"Slide n\u00E0y gi\u1EDBi thi\u1EC7u t\u1ED5ng quan v\u1EC1 c\u01A1 ch\u1EBF gom r\u00E1c trong Java, nh\u1EA5n m\u1EA1nh vai tr\u00F2 c\u1EE7a n\u00F3 trong vi\u1EC7c qu\u1EA3n l\u00FD b\u1ED9 nh\u1EDB t\u1EF1 \u0111\u1ED9ng v\u00E0 gi\u00FAp tr\u00E1nh c\u00E1c l\u1ED7i li\u00EAn quan \u0111\u1EBFn b\u1ED9 nh\u1EDB."},{"SlideNumber":2,"Title":"Nguy\u00EAn l\u00FD ho\u1EA1t \u0111\u1ED9ng c\u1EE7a gom r\u00E1c","ImageKeyword":"Flat vector illustration, minimalist corporate style, abstract flowing arrows moving from used to free space, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Ph\u00E1t hi\u1EC7n \u0111\u1ED1i t\u01B0\u1EE3ng kh\u00F4ng c\u00F2n tham chi\u1EBFu","Thu h\u1ED3i b\u1ED9 nh\u1EDB c\u1EE7a \u0111\u1ED1i t\u01B0\u1EE3ng \u0111\u00F3","Gi\u1EA3i ph\u00F3ng t\u00E0i nguy\u00EAn cho h\u1EC7 th\u1ED1ng"],"SpeakerNotes":"Tr\u00ECnh b\u00E0y c\u00E1ch gom r\u00E1c x\u00E1c \u0111\u1ECBnh c\u00E1c \u0111\u1ED1i t\u01B0\u1EE3ng kh\u00F4ng c\u00F2n \u0111\u01B0\u1EE3c tham chi\u1EBFu trong ch\u01B0\u01A1ng tr\u00ECnh v\u00E0 ti\u1EBFn h\u00E0nh thu h\u1ED3i b\u1ED9 nh\u1EDB c\u1EE7a ch\u00FAng \u0111\u1EC3 t\u00E1i s\u1EED d\u1EE5ng."},{"SlideNumber":3,"Title":"C\u00E1c thu\u1EADt to\u00E1n gom r\u00E1c ph\u1ED5 bi\u1EBFn","ImageKeyword":"Flat vector illustration, minimalist corporate style, three distinct abstract shapes representing different algorithms, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Mark-and-Sweep","Copying","Generational"],"SpeakerNotes":"Gi\u1EDBi thi\u1EC7u ba thu\u1EADt to\u00E1n gom r\u00E1c ch\u00EDnh: Mark-and-Sweep, Copying v\u00E0 Generational, m\u1ED7i thu\u1EADt to\u00E1n c\u00F3 c\u00E1ch th\u1EE9c ho\u1EA1t \u0111\u1ED9ng v\u00E0 \u01B0u \u0111i\u1EC3m ri\u00EAng."},{"SlideNumber":4,"Title":"\u01AFu \u0111i\u1EC3m c\u1EE7a c\u01A1 ch\u1EBF gom r\u00E1c trong Java","ImageKeyword":"Flat vector illustrati