INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('f838344b-7054-47ab-b08a-e1634a736e98', '2096eb83-96f9-4794-a116-4d2e6ca026bb', N'Công cụ phát triển WPF và ngôn ngữ XAML', N'Tìm hiểu về các công cụ phát triển WPF và ngôn ngữ XAML.', 2, N'Visual Studio cho WPF, khái niệm XAML, cú pháp XAML cơ bản.', NULL, NULL, NULL, '2026-06-17T08:42:15.944546', NULL, NULL, NULL, NULL, N'Failed', '2026-06-17T08:43:44.364574', N'A task was canceled.', NULL, N'NotGenerated', NULL, NULL, N'NotGenerated', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1);
INSERT INTO [dbo].[Lessons] ([Id], [ModuleId], [Title], [Description], [OrderIndex], [ContentSeed], [VideoUrl], [AudioUrl], [Duration], [CreatedAt], [UpdatedAt], [TeachingScript], [SlideOutlineJson], [VoiceoverPlanJson], [ContentGenerationStatus], [ContentGeneratedAt], [ContentGenerationError], [AudioSegmentsJson], [AudioGenerationStatus], [AudioGenerationError], [AudioGeneratedAt], [VideoGenerationStatus], [VideoGenerationError], [VideoGeneratedAt], [PresenterOverlayVideoPath], [PresenterOverlayStatus], [PresenterOverlayGeneratedAt], [PresenterOverlaySourceHash], [NarrationVoiceKey], [TranscriptText], [VoiceTutorEnabled]) VALUES ('22a7e14b-c963-49b4-82be-e3eac3d95276', '35efa6cd-f86b-4ec0-8a31-da893ac115c8', N'Xây dựng và hiện thực lớp con', N'Tạo lớp con và kế thừa thuộc tính, phương thức.', 3, N'Xây dựng và hiện thực lớp con', N'/storage/video/22a7e14b-c963-49b4-82be-e3eac3d95276.mp4', N'/storage/audio/22a7e14b-c963-49b4-82be-e3eac3d95276.mp3', 40, '2026-06-12T13:11:29.007844', '2026-06-12T13:39:16.336024', N'Chào các bạn, trong bài học hôm nay, chúng ta sẽ tìm hiểu cách xây dựng và hiện thực lớp con trong lập trình hướng đối tượng bằng Java. Lớp con là lớp kế thừa các thuộc tính và phương thức từ lớp cha, giúp tái sử dụng mã nguồn và mở rộng chức năng. Trước tiên, chúng ta sẽ xem cách tạo lớp con và kế thừa các thành phần từ lớp cha. Tiếp theo, chúng ta sẽ tìm hiểu cách ghi đè phương thức (overriding) để thay đổi hành vi của lớp con. Cuối cùng, chúng ta sẽ thảo luận về các lưu ý khi xây dựng lớp con để đảm bảo tính kế thừa và đa hình hiệu quả. Hãy bắt đầu nhé!', N'[{"SlideNumber":1,"Title":"Kh\u00E1i ni\u1EC7m l\u1EDBp con trong Java","ImageKeyword":"Flat vector illustration, minimalist corporate style, a tree with branches extending outward symbolizing inheritance, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["L\u1EDBp con k\u1EBF th\u1EEBa t\u1EEB l\u1EDBp cha","T\u00E1i s\u1EED d\u1EE5ng thu\u1ED9c t\u00EDnh v\u00E0 ph\u01B0\u01A1ng th\u1EE9c","M\u1EDF r\u1ED9ng v\u00E0 t\u00F9y bi\u1EBFn ch\u1EE9c n\u0103ng"],"SpeakerNotes":"Slide n\u00E0y gi\u1EDBi thi\u1EC7u kh\u00E1i ni\u1EC7m l\u1EDBp con trong Java. L\u1EDBp con l\u00E0 l\u1EDBp \u0111\u01B0\u1EE3c t\u1EA1o ra d\u1EF1a tr\u00EAn l\u1EDBp cha, k\u1EBF th\u1EEBa c\u00E1c thu\u1ED9c t\u00EDnh v\u00E0 ph\u01B0\u01A1ng th\u1EE9c \u0111\u1EC3 t\u00E1i s\u1EED d\u1EE5ng v\u00E0 m\u1EDF r\u1ED9ng ch\u1EE9c n\u0103ng."},{"SlideNumber":2,"Title":"T\u1EA1o l\u1EDBp con v\u00E0 k\u1EBF th\u1EEBa","ImageKeyword":"Flat vector illustration, minimalist corporate style, interlocking puzzle pieces representing class inheritance, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["S\u1EED d\u1EE5ng t\u1EEB kh\u00F3a extends","L\u1EDBp con th\u1EEBa h\u01B0\u1EDFng thu\u1ED9c t\u00EDnh, ph\u01B0\u01A1ng th\u1EE9c","C\u00FA ph\u00E1p \u0111\u01A1n gi\u1EA3n, r\u00F5 r\u00E0ng"],"SpeakerNotes":"\u1EDE slide n\u00E0y, ch\u00FAng ta h\u1ECDc c\u00E1ch t\u1EA1o l\u1EDBp con b\u1EB1ng t\u1EEB kh\u00F3a extends trong Java. L\u1EDBp con s\u1EBD t\u1EF1 \u0111\u1ED9ng th\u1EEBa h\u01B0\u1EDFng c\u00E1c thu\u1ED9c t\u00EDnh v\u00E0 ph\u01B0\u01A1ng th\u1EE9c c\u1EE7a l\u1EDBp cha, gi\u00FAp gi\u1EA3m thi\u1EC3u m\u00E3 l\u1EB7p."},{"SlideNumber":3,"Title":"Ghi \u0111\u00E8 ph\u01B0\u01A1ng th\u1EE9c (Overriding)","ImageKeyword":"Flat vector illustration, minimalist corporate style, a chameleon changing colors symbolizing method overriding, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Thay \u0111\u1ED5i h\u00E0nh vi ph\u01B0\u01A1ng th\u1EE9c l\u1EDBp cha","C\u00F9ng t\u00EAn, c\u00F9ng tham s\u1ED1","S\u1EED d\u1EE5ng @Override \u0111\u1EC3 \u0111\u1EA3m b\u1EA3o"],"SpeakerNotes":"Slide n\u00E0y tr\u00ECnh b\u00E0y v\u1EC1 ghi \u0111\u00E8 ph\u01B0\u01A1ng th\u1EE9c, cho ph\u00E9p l\u1EDBp con thay \u0111\u1ED5i h\u00E0nh vi c\u1EE7a ph\u01B0\u01A1ng th\u1EE9c k\u1EBF th\u1EEBa t\u1EEB l\u1EDBp cha b\u1EB1ng c\u00E1ch \u0111\u1ECBnh ngh\u0129a l\u1EA1i ph\u01B0\u01A1ng th\u1EE9c \u0111\u00F3."},{"SlideNumber":4,"Title":"L\u01B0u \u00FD khi x\u00E2y d\u1EF1ng l\u1EDBp con","ImageKeyword":"Flat vector illustration, minimalist corporate style, balanced scales symbolizing design considerations, clean aesthetics, NO TEXT, NO NUMBERS, NO WORDS","BulletPoints":["Tr\u00E1nh k\u1EBF th\u1EEBa qu\u00E1 s\u00E2u","Gi\u1EEF t\u00EDnh \u0111\u00F3ng g\u00F3i v\u00E0 b\u1EA3o m\u1EADt","S\u1EED d\u1EE5ng \u0111a h\u00ECnh hi\u1EC7u qu\u1EA3"],"SpeakerNotes":"Cu\u1ED1i c\u00F9ng, slide n\u00E0y n\u00EAu c\u00E1c l\u01B0u \u00FD khi x\u00E2y d\u1EF1ng l\u1EDBp con nh\u01B0 tr\u00E1nh k\u1EBF th\u1EEBa qu\u00E1 s\u00E2u g\u00E2y ph\u1EE9c t\u1EA1p, gi\u1EEF t\u00EDnh \u0111\u00F3ng g\u00F3i v\u00E0 b\u1EA3o m\u1EADt, \u0111\u1ED3ng th\u1EDDi t\u1EADn d\u1EE5ng \u0111a h\u00ECnh \u0111\u1EC3 thi\u1EBFt k\u1EBF linh ho\u1EA1t."}]', N'{"EstimatedDurationMinutes":12,"Tone":"Th\u00E2n thi\u1EC7n, r\u00F5 r\u00E0ng, truy\u1EC1n c\u1EA3m","Pacing":"Ch\u1EADm v\u1EEBa ph\u1EA3i, nh\u1EA5n m\u1EA1nh c\u00E1c kh\u00E1i ni\u1EC7m quan tr\u1ECDng","TargetAudience":"Sinh vi\u00EAn \u0111\u1EA1i h\u1ECDc ng\u00E0nh c\u00F4ng ngh\u1EC7 th\u00F4ng tin, m\u1EDBi h\u1ECDc l\u1EADp tr\u00ECnh h\u01B0\u1EDBng \u0111\u1ED1i t\u01B0\u1EE3ng","PronunciationNotes":"Ph\u00E1t \u00E2m r\u00F5 r\u00E0ng c\u00E1c thu\u1EADt ng\u1EEF chuy\u00EAn ng\u00E0nh nh\u01B0 \u0027l\u1EDBp con\u0027, \u0027k\u1EBF th\u1EEBa\u0027, \u0027ghi \u0111\u00E8\u0027, \u0027\u0111a h\u00ECnh\u0027, tr\u00E1nh n\u00F3i nhanh \u0111\u1EC3 ng\u01B0\u1EDDi h\u1ECDc d\u1EC5 theo d\u00F5i"}', N'Completed', '2026-06-12T13:37:54.906270', NULL, N'[{"SlideNumber":1,"Title":"Kh\u00E1i ni\u1EC7m l\u1EDBp con trong Java","NarrationText":"Slide n\u00E0y gi\u1EDBi thi\u1EC7u kh\u00E1i ni\u1EC7m l\u1EDBp con trong Java. L\u1EDBp con l\u00E0 l\u1EDBp \u0111\u01B0\u1EE3c t\u1EA1o ra d\u1EF1a tr\u00EAn l\u1EDBp cha, k\u1EBF th\u1EEBa c\u00E1c thu\u1ED9c t\u00EDnh v\u00E0 ph\u01B0\u