INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('1fb1f1d2-de53-4456-ab5e-07bfebd0c4d2', 'fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 1, N'Assistant', N'Để học tốt môn lập trình hướng đối tượng, bạn nên thực hành nhiều bằng cách viết code, đọc kỹ lý thuyết và làm bài tập liên quan đến đối tượng, lớp, đóng gói,. kế thừa và đa hình. Ngoài ra, đừng ngại hỏi khi không hiểu và tham khảo thêm ví dụ thực tế để nhớ lâu hơn.', N'Mixed', NULL, 18.857142857142858, 1, '2026-06-12T13:20:48.203608', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('deb58df6-1fae-48b3-8828-4b7d9087bf82', '6b39a7e1-9a6b-40ad-9604-417c6465af26', 1, N'User', N'진짜요.', N'Lesson', NULL, NULL, 0, '2026-06-12T15:50:36.301088', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('ae41bde3-03df-4c1a-9708-57f7ddd203c3', '6b39a7e1-9a6b-40ad-9604-417c6465af26', 1, N'Assistant', N'"진짜요" trong tiếng Hàn có nghĩa là "thật sao" hoặc "đúng vậy". Bạn có thể hỏi thêm nếu muốn hiểu rõ hơn nhé!', N'Mixed', NULL, 7.571428571428571, 1, '2026-06-12T15:50:36.312253', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('3d7fed92-a8b6-4318-b13b-5c0f2ae5bef1', 'fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 1, N'Assistant', N'Trong AI, OOP rất quan trọng vì giúp bạn tổ chức mã nguồn rõ ràng, dễ quản lý và mở rộng. Ví dụ, bạn có thể tạo lớp để mô tả các thuật toán hay mô hình AI, rồi tái sử dụng hoặc kế thừa chúng khi cần. Đây là nền tảng tốt để phát triển các ứng dụng AI phức tạp.', N'Mixed', NULL, 18.357142857142858, 1, '2026-06-12T13:21:25.681811', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('211205ca-5984-4152-9527-60579129f8e9', '6b39a7e1-9a6b-40ad-9604-417c6465af26', 1, N'User', N'Vậy cháu gọi cho anh nghe. Chứ cháu? cái học môn trí tuệ nhân tạo này thì tôi làm được cái gì?', N'Lesson', NULL, NULL, 0, '2026-06-17T08:39:39.431473', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('9135f9f3-7d2a-4a54-9c2f-687020b002a7', 'fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 1, N'Assistant', N'Học tốt lập trình hướng đối tượng là nền tảng quan trọng để trở thành chuyên gia phần mềm, nhưng bạn còn cần rèn luyện thêm kỹ năng thực hành,. giải quyết vấn đề và cập nhật công nghệ mới. OOP giúp bạn thiết kế phần mềm rõ ràng, dễ bảo trì và mở rộng hơn.', N'Mixed', NULL, 18.07142857142857, 1, '2026-06-12T13:20:15.112000', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('b0d91d67-33b3-4748-857d-6abf61cfb150', '6b39a7e1-9a6b-40ad-9604-417c6465af26', 1, N'User', N'cho tôi biết những lĩnh vực con của trí tuệ nhân tạo.', N'Lesson', NULL, NULL, 0, '2026-06-12T15:51:10.089739', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('5c9a363b-fce3-494b-945d-c2b5dbf99fdb', '6b39a7e1-9a6b-40ad-9604-417c6465af26', 1, N'Assistant', N'Chào em, học Trí tuệ nhân tạo sẽ giúp em phát triển các hệ thống thông minh, ví dụ như tạo ra chatbot, xe tự lái, hoặc các công cụ phân tích dữ liệu lớn. Em có thể làm việc trong nhiều lĩnh vực công nghệ cao, từ nghiên cứu đến phát triển sản phẩm.', N'Mixed', NULL, 17.642857142857142, 1, '2026-06-17T08:39:39.518412', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('5b857aea-6496-46f6-af43-c30aeee43008', 'fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 1, N'User', N'Nếu tôi học tốt môn lập trình hướng đối tượng thì tôi có trở thành một chuyên gia phần mềm hay không?', N'Lesson', NULL, NULL, 0, '2026-06-12T13:20:15.099142', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('a4a14f4d-1283-4166-aa80-c4517b82a825', 'fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 1, N'User', N'Vậy ở trong AI có liên quan gì đến OOP không? Nếu mà trong tương lai tôi muốn học về trí tuệ nhân tạo.', N'Lesson', NULL, NULL, 0, '2026-06-12T13:21:25.681623', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('f09261c7-996e-43fd-b2a8-c9c7694b442f', '6b39a7e1-9a6b-40ad-9604-417c6465af26', 1, N'Assistant', N'Trí tuệ nhân tạo có các lĩnh vực con như học máy, xử lý ngôn ngữ tự nhiên, thị giác máy tính và robot. Mỗi lĩnh vực tập trung vào một khía cạnh khác nhau của trí thông minh máy tính. Ví dụ, học máy giúp máy tính tự học từ dữ liệu mà không cần lập trình rõ ràng.', N'Mixed', NULL, 18.5, 1, '2026-06-12T15:51:10.089893', NULL);
INSERT INTO [dbo].[LessonVoiceMessages] ([Id], [SessionId], [TurnNumber], [Role], [ContentText], [ContentSourceType], [AudioUrl], [AudioDurationSeconds], [SequenceIndex], [CreatedAt], [UpdatedAt]) VALUES ('ca0e3746-720e-4115-9dcd-df9214db1660', 'fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 1, N'User', N'chị ờ em đi cho em hỏi là làm thế nào để học tốt cái môn này?', N'Lesson', NULL, NULL, 0, '2026-06-12T13:20:48.203396', NULL);
