INSERT INTO [dbo].[LessonVoiceSessions] ([Id], [LessonId], [CourseId], [UserId], [Status], [StartedAt], [LastActivityAt], [EndedAt], [LastPausedVideoTimeSeconds], [VoiceProfileKey], [ContextScope], [ConversationSummary], [CreatedAt], [UpdatedAt]) VALUES ('fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 'a9a5909a-8f26-4b20-a94b-3a574e0fb7e4', '444403f4-83a5-4542-a8cb-fc1378fb6ce0', '680028f3-06a9-41ad-b64c-87721edd6a03', N'Active', '2026-06-12T13:19:45.902274', '2026-06-12T13:21:25.681873', NULL, 16.521374, N'vi-VN-HoaiMyNeural', N'LessonWithCourseAndExternalKnowledge', NULL, '2026-06-12T13:19:45.902299', NULL);
INSERT INTO [dbo].[LessonVoiceTurns] ([Id], [SessionId], [TurnNumber], [Status], [PlaybackPausedAtSeconds], [UserAudioUrl], [TranscriptionText], [TranscriptionConfidence], [AnswerText], [AnswerSourceSummary], [ErrorCode], [ErrorMessage], [StartedAt], [CompletedAt], [CreatedAt], [UpdatedAt]) VALUES ('93bafa21-bb48-4f29-aee6-033304858c94', '6b39a7e1-9a6b-40ad-9604-417c6465af26', 1, N'Completed', 1.055492, NULL, N'Vậy cháu gọi cho anh nghe. Chứ cháu? cái học môn trí tuệ nhân tạo này thì tôi làm được cái gì?', 1.00, N'Chào em, học Trí tuệ nhân tạo sẽ giúp em phát triển các hệ thống thông minh, ví dụ như tạo ra chatbot, xe tự lái, hoặc các công cụ phân tích dữ liệu lớn. Em có thể làm việc trong nhiều lĩnh vực công nghệ cao, từ nghiên cứu đến phát triển sản phẩm.', N'Mixed', NULL, NULL, '2026-06-17T08:39:18.021731', '2026-06-17T08:39:39.431276', '2026-06-17T08:39:18.021743', NULL);
INSERT INTO [dbo].[LessonVoiceTurns] ([Id], [SessionId], [TurnNumber], [Status], [PlaybackPausedAtSeconds], [UserAudioUrl], [TranscriptionText], [TranscriptionConfidence], [AnswerText], [AnswerSourceSummary], [ErrorCode], [ErrorMessage], [StartedAt], [CompletedAt], [CreatedAt], [UpdatedAt]) VALUES ('8c089803-f13e-4833-89b2-07f05a1980e6', 'fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 1, N'Completed', 16.521374, NULL, N'Nếu tôi học tốt môn lập trình hướng đối tượng thì tôi có trở thành một chuyên gia phần mềm hay không?', 1.00, N'Học tốt lập trình hướng đối tượng là nền tảng quan trọng để trở thành chuyên gia phần mềm, nhưng bạn còn cần rèn luyện thêm kỹ năng thực hành,. giải quyết vấn đề và cập nhật công nghệ mới. OOP giúp bạn thiết kế phần mềm rõ ràng, dễ bảo trì và mở rộng hơn.', N'Mixed', NULL, NULL, '2026-06-12T13:19:53.206443', '2026-06-12T13:20:15.099112', '2026-06-12T13:19:53.206448', NULL);
INSERT INTO [dbo].[LessonVoiceTurns] ([Id], [SessionId], [TurnNumber], [Status], [PlaybackPausedAtSeconds], [UserAudioUrl], [TranscriptionText], [TranscriptionConfidence], [AnswerText], [AnswerSourceSummary], [ErrorCode], [ErrorMessage], [StartedAt], [CompletedAt], [CreatedAt], [UpdatedAt]) VALUES ('a3376068-c78c-4775-829b-0de2c2e6c900', '6b39a7e1-9a6b-40ad-9604-417c6465af26', 1, N'Completed', 0.0, NULL, N'진짜요.', 1.00, N'"진짜요" trong tiếng Hàn có nghĩa là "thật sao" hoặc "đúng vậy". Bạn có thể hỏi thêm nếu muốn hiểu rõ hơn nhé!', N'Mixed', NULL, NULL, '2026-06-12T15:50:26.127937', '2026-06-12T15:50:36.301054', '2026-06-12T15:50:26.127942', NULL);
INSERT INTO [dbo].[LessonVoiceTurns] ([Id], [SessionId], [TurnNumber], [Status], [PlaybackPausedAtSeconds], [UserAudioUrl], [TranscriptionText], [TranscriptionConfidence], [AnswerText], [AnswerSourceSummary], [ErrorCode], [ErrorMessage], [StartedAt], [CompletedAt], [CreatedAt], [UpdatedAt]) VALUES ('ef09e882-7cd0-42c4-9830-5233ffde2140', 'fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 1, N'Completed', 16.521374, NULL, N'Vậy ở trong AI có liên quan gì đến OOP không? Nếu mà trong tương lai tôi muốn học về trí tuệ nhân tạo.', 1.00, N'Trong AI, OOP rất quan trọng vì giúp bạn tổ chức mã nguồn rõ ràng, dễ quản lý và mở rộng. Ví dụ, bạn có thể tạo lớp để mô tả các thuật toán hay mô hình AI, rồi tái sử dụng hoặc kế thừa chúng khi cần. Đây là nền tảng tốt để phát triển các ứng dụng AI phức tạp.', N'Mixed', NULL, NULL, '2026-06-12T13:21:12.447048', '2026-06-12T13:21:25.681616', '2026-06-12T13:21:12.447048', NULL);
INSERT INTO [dbo].[LessonVoiceTurns] ([Id], [SessionId], [TurnNumber], [Status], [PlaybackPausedAtSeconds], [UserAudioUrl], [TranscriptionText], [TranscriptionConfidence], [AnswerText], [AnswerSourceSummary], [ErrorCode], [ErrorMessage], [StartedAt], [CompletedAt], [CreatedAt], [UpdatedAt]) VALUES ('37944b57-515c-4549-a686-54a671be9afa', '6b39a7e1-9a6b-40ad-9604-417c6465af26', 1, N'Completed', 0.0, NULL, N'cho tôi biết những lĩnh vực con của trí tuệ nhân tạo.', 1.00, N'Trí tuệ nhân tạo có các lĩnh vực con như học máy, xử lý ngôn ngữ tự nhiên, thị giác máy tính và robot. Mỗi lĩnh vực tập trung vào một khía cạnh khác nhau của trí thông minh máy tính. Ví dụ, học máy giúp máy tính tự học từ dữ liệu mà không cần lập trình rõ ràng.', N'Mixed', NULL, NULL, '2026-06-12T15:50:55.933705', '2026-06-12T15:51:10.089737', '2026-06-12T15:50:55.933706', NULL);
INSERT INTO [dbo].[LessonVoiceTurns] ([Id], [SessionId], [TurnNumber], [Status], [PlaybackPausedAtSeconds], [UserAudioUrl], [TranscriptionText], [TranscriptionConfidence], [AnswerText], [AnswerSourceSummary], [ErrorCode], [ErrorMessage], [StartedAt], [CompletedAt], [CreatedAt], [UpdatedAt]) VALUES ('5ed8c482-33d9-4965-bfa1-dbf8ac44744c', 'fb0abe7f-9b81-4477-ae25-b7ee21ba8b02', 1, N'Completed', 16.521374, NULL, N'chị ờ em đi cho em hỏi là làm thế nào để học tốt cái môn này?', 1.00, N'Để học tốt môn lập trình hướng đối tượng, bạn nên thực hành nhiều bằng cách viết code, đọc kỹ lý thuyết và làm bài tập liên quan đến đối tượng, lớp, đóng gói,. kế thừa và đa hình. Ngoài ra, đừng ngại hỏi khi không hiểu và tham khảo thêm ví dụ thực tế để nhớ lâu hơn.', N'Mixed', NULL, NULL, '2026-06-12T13:20:32.340142', '2026-06-12T13:20:48.203390', '2026-06-12T13:20:32.340143', NULL);
