INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('adadb3d6-c2fc-4422-b102-314c1bb225dd', '1cd6f755-ac32-45e3-b852-eb86ad3ad431', N'Phương pháp nào giúp TTNT học từ dữ liệu bằng cách xây dựng mô hình dựa trên các tầng mạng nơ-ron?', N'Học sâu sử dụng mạng nơ-ron nhiều tầng để trích xuất đặc trưng phức tạp từ dữ liệu.', 1, '2026-06-12T15:31:04.633491', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('ff111ea0-bd96-4fb8-999f-314e3df0ab40', 'f64fd660-aa5e-404b-bbe5-2c74df876a45', N'Yếu tố nào quan trọng nhất để bảo mật dữ liệu trong TTNT?', N'Bảo mật dữ liệu đòi hỏi các biện pháp kỹ thuật và chính sách nghiêm ngặt để ngăn chặn truy cập trái phép.', 2, '2026-06-12T15:44:54.116591', NULL);
