INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('8fd100d8-973a-46ac-b47a-325d3c8761b9', '8f88db29-fc17-4db2-a174-05a2796f68ac', N'Ngôn ngữ nào được biết đến là ngôn ngữ lập trình hướng đối tượng thuần túy?', N'Java được thiết kế như một ngôn ngữ lập trình hướng đối tượng thuần túy, mọi thứ đều là đối tượng.', 2, '2026-06-12T13:13:58.588855', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('98ea4e00-e4ef-40ec-8053-32ccbc490417', 'b6c6a48b-5f1b-4005-980b-063d50b903a4', N'TTNT được ứng dụng như thế nào trong sáng tạo nội dung số?', N'TTNT giúp tự động tạo ra nội dung số đa dạng và phong phú, tiết kiệm thời gian và công sức cho người sáng tạo.', 1, '2026-06-12T15:42:05.857114', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('ec4c95bf-9319-43d2-94a6-33b02f7a930b', '3b2a4236-b306-42f5-8949-e9a766bc5e55', N'Để tạo một luồng mới trong Java, ta cần làm gì?', N'Có thể tạo luồng mới bằng cách kế thừa lớp Thread hoặc cài đặt giao diện Runnable.', 3, '2026-06-12T14:04:29.003010', NULL);
