INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('39be6a95-6dce-4e0f-a9d4-353107fe0180', '220190da-6f8c-4f94-9498-d2d5da564106', N'Yếu tố nào quan trọng nhất khi đánh giá hệ thống TTNT?', N'Đánh giá hệ thống tập trung vào hiệu quả và độ chính xác của mô hình trong thực tế.', 2, '2026-06-12T15:47:44.275793', NULL);
