INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('21ce4647-6df6-4da7-b54b-35ed267fe9f2', '8f5986ff-a413-486f-94fd-27901954bd28', N'Giai đoạn nào đánh dấu sự phát triển đầu tiên của TTNT?', N'Những năm 1950 được xem là thời kỳ đầu tiên của TTNT với các nghiên cứu cơ bản và thuật toán ban đầu.', 2, '2026-06-12T15:27:34.913929', NULL);
