INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('5a8e3c64-98fc-4d61-87aa-5396d4eee27c', '1868f7e8-92e4-42d1-857e-5ee13052bf3f', N'Công nghệ nào thường kết hợp với TTNT trong kỹ thuật?', N'Công nghệ cảm biến và phân tích dữ liệu thường được kết hợp với TTNT để thu thập và xử lý thông tin.', 2, '2026-06-12T15:36:50.793150', NULL);
