INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('437441ac-c810-4d27-a910-555abecfe49d', '87a183c2-40ac-4fcc-8eb1-7530863649d9', N'Trong phân cấp kế thừa, lớp con có thể làm gì với phương thức của lớp cha?', N'Lớp con có thể ghi đè (overriding) phương thức của lớp cha để thay đổi hành vi.', 2, '2026-06-12T13:39:34.589159', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('ac586f92-8edc-4781-8b8e-57db945f86fa', '1cd6f755-ac32-45e3-b852-eb86ad3ad431', N'Phương pháp học máy trong TTNT chủ yếu dựa vào điều gì để cải thiện hiệu suất?', N'Học máy sử dụng dữ liệu huấn luyện để điều chỉnh mô hình và nâng cao độ chính xác.', 3, '2026-06-12T15:31:04.633518', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('6c42fae9-c6ed-4b59-89d9-5849b7122937', 'f1ecca4e-ef57-48f3-b894-a3bbd2e5af5a', N'Trí tuệ nhân tạo (TTNT) được định nghĩa là gì?', N'TTNT là lĩnh vực nghiên cứu và phát triển các hệ thống máy tính có khả năng thực hiện các nhiệm vụ thông minh như con người.', 1, '2026-06-12T15:48:22.691814', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('dfbc74ea-644c-4761-840c-594af4cd32c6', '838e75c5-285d-4380-b612-8bf25d8ae60d', N'Từ khóa nào dùng để khai báo một lớp trong Java?', N'Từ khóa class được dùng để khai báo một lớp trong Java.', 2, '2026-06-12T13:24:38.177895', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('77d9f763-6fd7-4d9b-a69d-59642171dc20', 'f1ecca4e-ef57-48f3-b894-a3bbd2e5af5a', N'Phương pháp nào sau đây là cơ bản trong cách TTNT học từ dữ liệu?', N'Học máy là phương pháp chính giúp TTNT học và cải thiện hiệu suất dựa trên dữ liệu.', 3, '2026-06-12T15:48:22.691827', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('fa54d39e-cf34-4cf1-94d5-5a0522edf2b9', '32559743-ff73-45cf-8879-91fc9c5bed0c', N'Cơ chế gom rác trong Java dùng để làm gì?', N'Cơ chế gom rác giúp tự động thu hồi bộ nhớ không còn được sử dụng, tránh rò rỉ bộ nhớ.', 1, '2026-06-12T13:51:12.924101', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('185f148d-8e49-4a88-9ff9-5abe9498048a', 'f1ecca4e-ef57-48f3-b894-a3bbd2e5af5a', N'TTNT được ứng dụng trong lĩnh vực y tế để làm gì?', N'TTNT giúp cải thiện chăm sóc sức khỏe thông qua phân tích dữ liệu và hỗ trợ chẩn đoán.', 7, '2026-06-12T15:48:22.691842', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('979e2fa0-0538-4b06-980f-5b1cf435a23c', '60b2fe74-956c-479d-869f-5c33df9e889b', N'Điểm khác biệt chính giữa interface và lớp trừu tượng trong Java là gì?', N'Interface chỉ chứa các phương thức trừu tượng và hằng số, trong khi lớp trừu tượng có thể chứa cả phương thức đã cài đặt và biến thành viên.', 1, '2026-06-12T13:54:12.423890', NULL);
