INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('e7ce8795-b312-418f-94b4-5d040b0e413d', '24387b8f-7e19-43ff-b5a8-f7e29faca77f', N'Kiểu dữ liệu trừu tượng (ADT) trong OOP là gì?', N'ADT là kiểu dữ liệu được định nghĩa bởi hành vi và các phép toán mà không quan tâm đến cách cài đặt bên trong.', 1, '2026-06-12T13:17:18.709363', NULL);
