INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('132c80c8-3b38-41aa-bf08-5f8bcf86bc6f', 'c8940998-5b63-4ec2-8439-cda281f35ec0', N'Khi nào cần sử dụng ép kiểu (casting) trong Java?', N'Ép kiểu được dùng khi muốn chuyển đổi kiểu đối tượng từ lớp cha sang lớp con hoặc ngược lại để truy cập các thành phần đặc trưng.', 2, '2026-06-12T13:42:34.652250', NULL);
