INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('e00f112a-288e-4d5e-a9cb-ec92a8054b79', 'f535f8b6-f37a-421e-a47b-45a548ec1eab', N'Vai trò của TTNT trong truyền thông là gì?', N'TTNT giúp cá nhân hóa nội dung và tối ưu hóa việc truyền tải thông tin đến người dùng.', 2, '2026-06-12T15:35:08.358275', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('00ed0368-0590-4348-b2fb-ecf70c57b159', 'f1ecca4e-ef57-48f3-b894-a3bbd2e5af5a', N'Dữ liệu lớn (Big Data) có vai trò gì trong TTNT?', N'Dữ liệu lớn cung cấp nguồn thông tin phong phú để TTNT khai thác và học hỏi, nâng cao hiệu quả ứng dụng.', 4, '2026-06-12T15:48:22.691831', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('f8621204-5a4a-4511-bd5f-ed0d109c0de7', '6e5d842a-b370-484f-9c44-49f652a8db1f', N'Java Collections Framework dùng để làm gì?', N'Collections Framework cung cấp các cấu trúc dữ liệu và thuật toán để quản lý và thao tác tập hợp đối tượng hiệu quả.', 1, '2026-06-12T13:58:36.887320', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('b75de173-2552-4255-8aa3-efd2ff79e8c8', '2a20f468-0067-41f4-8404-8e3d3907d9bb', N'IBM Watson là gì trong lĩnh vực trí tuệ nhân tạo?', N'IBM Watson là nền tảng AI cung cấp dịch vụ phân tích và xử lý ngôn ngữ tự nhiên.', 1, '2026-06-12T15:40:52.850010', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('9e21fce2-30e9-4e2e-95a9-f01f87f6b3ca', 'f564e2ce-85a4-4b59-9ec4-7ed40d9621ec', N'Thành phần nào sau đây không phải là một phần của Swing?', N'AWT là thư viện giao diện cũ, không thuộc Swing.', 2, '2026-06-12T14:03:17.935706', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('6bbc6208-44df-4f1f-b2a5-f13f0096a74f', 'c3619ec4-3e7d-4acd-bb9d-b103a151ce65', N'Khi nào nên tạo Exception tùy chỉnh trong Java?', N'Khi muốn xử lý các lỗi đặc thù của ứng dụng mà các Exception có sẵn không thể mô tả chính xác.', 3, '2026-06-12T13:50:20.309821', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('607357bc-83da-47cd-ab7d-f3266f6576c0', '81a284b7-bc4d-428c-8faf-1706ad2da29e', N'Phát biểu nào sau đây đúng về lớp trừu tượng?', N'Lớp trừu tượng không thể khởi tạo đối tượng và có thể chứa cả phương thức đã định nghĩa và chưa định nghĩa.', 3, '2026-06-12T13:43:35.787419', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('b3cd0fc5-ef1e-4d5e-883e-f7177211fc1e', 'a1680a5e-587f-4cfc-aae7-74f1de2370be', N'Xu hướng phát triển chính của AI trong tương lai là gì?', N'AI sẽ tập trung vào cá nhân hóa và giải quyết các vấn đề thực tiễn một cách hiệu quả hơn.', 2, '2026-06-12T15:43:02.585399', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('e7a8bbde-500c-4ea1-bf94-f8454cc2a782', '96ac3a4f-7a61-4247-bde3-0b66b27516c1', N'Để sử dụng lớp trong một gói khác, ta dùng từ khóa nào?', N'Từ khóa ''import'' giúp nhập các lớp từ gói khác để sử dụng trong file hiện tại.', 3, '2026-06-12T13:55:04.840108', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('f1aeaf5a-383e-4bae-b91e-f96fe4d30396', 'f3f66dba-8e1f-48b5-b221-60b1270534b7', N'Cơ sở dữ liệu trong TTNT có vai trò gì?', N'Cơ sở dữ liệu giúp lưu trữ và truy xuất dữ liệu một cách có cấu trúc, hỗ trợ các thuật toán TTNT.', 2, '2026-06-12T15:32:03.829218', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('9bb00083-90e0-4b8b-b3f3-fb121f7ef526', '1b9fcf93-6c5b-4f51-9c13-052b1b71901a', N'Môi trường phát triển Java bao gồm thành phần nào chính?', N'Môi trường phát triển Java thường bao gồm JDK, JRE và các công cụ hỗ trợ lập trình.', 1, '2026-06-12T13:22:37.754670', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('b50497e1-4c99-4dfe-ba5e-fbe6f0548ef2', '9adc6f14-e900-4b71-9373-249888e4ba83', N'Tính đa hình trong lập trình hướng đối tượng là gì?', N'Tính đa hình cho phép các đối tượng thuộc các lớp khác nhau có thể được xử lý thông qua cùng một giao diện chung.', 1, '2026-06-12T13:21:53.923724', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('34ae8605-dd74-414c-961c-fe719442d37c', '35e4589c-2e68-44cb-a2a2-6ee7aafbd7fa', N'Phương thức Overriding giúp ích gì trong lập trình hướng đối tượng?', N'Nó cho phép đa hình, giúp lớp con thay đổi hành vi mà không làm ảnh hưởng đến lớp cha.', 3, '2026-06-12T13:37:14.531313', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('92d7731f-2e94-4483-91ff-ff64bff6f271', '838e75c5-285d-4380-b612-8bf25d8ae60d', N'Phần tử nào là điểm bắt đầu thực thi của chương trình Java?', N'Phương thức main() là điểm bắt đầu chạy chương trình Java.', 1, '2026-06-12T13:24:38.177885', NULL);
INSERT INTO [dbo].[QuizQuestions] ([Id], [QuizId], [QuestionText], [Explanation], [OrderIndex], [CreatedAt], [UpdatedAt]) VALUES ('db2b308a-2ed5-4f20-9b50-ff8097f78e76', '6e5d842a-b370-484f-9c44-49f652a8db1f', N'Lớp nào trong Collections Framework dùng để lưu trữ các phần tử theo thứ tự và cho phép truy cập theo chỉ số?', N'Lớp ArrayList lưu trữ phần tử theo thứ tự và hỗ trợ truy cập nhanh qua chỉ số.', 3, '2026-06-12T13:58:36.887328', NULL);
